import React, { useState, useCallback, useEffect } from 'react';
import { Header } from './components/Header';
import { FileUpload } from './components/FileUpload';
import { ProcessingView } from './components/ProcessingView';
import { ResultPreview } from './components/ResultPreview';
import { ImageCropper } from './components/ImageCropper';
import { AppStatus, ConversionResult, FileData, CroppedImage } from './types';
import { convertDocumentToLatex } from './services/geminiService';
import { AlertTriangle } from 'lucide-react';

const App: React.FC = () => {
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [currentFile, setCurrentFile] = useState<FileData | null>(null);
  const [result, setResult] = useState<ConversionResult | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [croppedImages, setCroppedImages] = useState<CroppedImage[]>([]);

  const processFile = async (fileData: FileData, images: CroppedImage[]) => {
    try {
      const htmlContent = await convertDocumentToLatex(fileData, images);

      setResult({
        content: htmlContent,
        fileName: fileData.name
      });
      setStatus(AppStatus.COMPLETE);
    } catch (error: any) {
      console.error(error);
      setStatus(AppStatus.ERROR);
      setErrorMessage(error.message || "Đã xảy ra lỗi không xác định trong quá trình xử lý.");
    }
  };

  const handleFileSelect = useCallback((file: File) => {
    setErrorMessage(null);
    setCroppedImages([]);

    const reader = new FileReader();
    reader.onload = async (e) => {
      const base64 = e.target?.result as string;
      const fileData: FileData = {
        name: file.name,
        size: file.size,
        type: file.type,
        base64: base64
      };

      setCurrentFile(fileData);

      if (file.type === 'application/pdf') {
        setStatus(AppStatus.CROP_SELECT);
      } else {
        setStatus(AppStatus.PROCESSING);
        processFile(fileData, []);
      }
    };
    reader.onerror = () => {
      setStatus(AppStatus.ERROR);
      setErrorMessage("Lỗi khi đọc file. Vui lòng thử lại.");
    };

    reader.readAsDataURL(file);
  }, []);

  // Handle Paste Event
  useEffect(() => {
    const handlePaste = (event: ClipboardEvent) => {
      if (status !== AppStatus.IDLE) return;

      const items = event.clipboardData?.items;
      if (!items) return;

      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const blob = items[i].getAsFile();
          if (blob) {
            const file = new File([blob], `pasted-image-${Date.now()}.png`, { type: blob.type });
            handleFileSelect(file);
            break;
          }
        }
      }
    };

    window.addEventListener('paste', handlePaste);
    return () => window.removeEventListener('paste', handlePaste);
  }, [status, handleFileSelect]);

  const handleCropComplete = (images: CroppedImage[]) => {
    setCroppedImages(images);
    if (currentFile) {
        setStatus(AppStatus.PROCESSING);
        processFile(currentFile, images);
    }
  };

  const handleCropCancel = () => {
      if (currentFile) {
          setStatus(AppStatus.PROCESSING);
          processFile(currentFile, []);
      }
  };

  const handleReset = () => {
    setStatus(AppStatus.IDLE);
    setCurrentFile(null);
    setResult(null);
    setErrorMessage(null);
    setCroppedImages([]);
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Header />

      <main className="flex-grow container mx-auto px-4 py-12 flex flex-col items-center justify-start gap-8 relative">

        {status === AppStatus.IDLE && (
          <div className="text-center max-w-2xl mx-auto space-y-4 mb-8">
            <h2 className="text-4xl font-extrabold text-gray-900 tracking-tight sm:text-5xl">
              Chuyển đổi <span className="text-blue-600">Tài liệu</span> sang <span className="text-blue-600">Word</span>
            </h2>
            <p className="text-lg text-gray-600 leading-relaxed">
              Giữ nguyên công thức toán học dưới dạng <strong>LaTeX code</strong> (ví dụ: $E=mc^2$). Hỗ trợ dán ảnh trực tiếp từ Clipboard.
            </p>
          </div>
        )}

        {status === AppStatus.IDLE && (
          <FileUpload onFileSelect={handleFileSelect} disabled={false} />
        )}

        {status === AppStatus.CROP_SELECT && currentFile && (
            <ImageCropper 
                fileData={currentFile} 
                onComplete={handleCropComplete}
                onCancel={handleCropCancel}
            />
        )}

        {(status === AppStatus.UPLOADING || status === AppStatus.PROCESSING) && currentFile && (
          <ProcessingView fileName={currentFile.name} isComplete={false} />
        )}

        {status === AppStatus.COMPLETE && result && (
          <ResultPreview result={result} onReset={handleReset} />
        )}

        {status === AppStatus.ERROR && (
          <div className="w-full max-w-lg bg-white rounded-xl shadow-lg border border-red-100 p-6 text-center space-y-4">
             <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto">
               <AlertTriangle className="w-8 h-8 text-red-600" />
             </div>
             <div>
               <h3 className="text-lg font-bold text-gray-900">Rất tiếc, đã xảy ra lỗi</h3>
               <p className="text-gray-600 mt-2">{errorMessage}</p>
             </div>
             <button 
                onClick={handleReset}
                className="px-6 py-2 bg-gray-900 text-white rounded-lg hover:bg-gray-800 transition-colors font-medium"
             >
               Thử lại
             </button>
          </div>
        )}

        {status === AppStatus.IDLE && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl mt-12">
            {[
              { title: "Định dạng Word", desc: "Xuất ra file .doc với cấu trúc văn bản rõ ràng, dễ dàng chỉnh sửa trên Microsoft Word." },
              { title: "Toán học LaTeX", desc: "Các công thức không bị vỡ lỗi hình ảnh mà được giữ nguyên mã nguồn LaTeX (trong dấu $)." },
              { title: "Dán ảnh (Paste)", desc: "Bạn có thể dán trực tiếp ảnh chụp màn hình (Ctrl+V) để chuyển đổi nhanh mà không cần lưu file." }
            ].map((feature, idx) => (
              <div key={idx} className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm hover:shadow-md transition-shadow">
                <h3 className="font-bold text-gray-900 mb-2">{feature.title}</h3>
                <p className="text-sm text-gray-500 leading-relaxed">{feature.desc}</p>
              </div>
            ))}
          </div>
        )}

      </main>

      <footer className="py-6 border-t border-gray-200 bg-white">
        <div className="container mx-auto px-4 text-center text-sm text-gray-500">
          © {new Date().getFullYear()} AI Document Converter. All rights reserved.
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useRef, useState } from 'react';
import { UploadCloud, FileType, AlertCircle, ClipboardPaste } from 'lucide-react';

interface FileUploadProps {
  onFileSelect: (file: File) => void;
  disabled: boolean;
}

export const FileUpload: React.FC<FileUploadProps> = ({ onFileSelect, disabled }) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const allowedTypes = [
    'application/pdf',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document', // .docx
    'text/plain', // .txt
    'application/rtf', // .rtf
    'text/rtf', // .rtf alternative
    'image/png',
    'image/jpeg'
  ];

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    if (!disabled) setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (disabled) return;

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      validateAndProcessFile(e.dataTransfer.files[0]);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      validateAndProcessFile(e.target.files[0]);
    }
  };

  const validateAndProcessFile = (file: File) => {
    setError(null);

    const extension = file.name.split('.').pop()?.toLowerCase();
    const isAllowedExtension = ['pdf', 'docx', 'txt', 'rtf', 'png', 'jpg', 'jpeg'].includes(extension || '');

    if (!allowedTypes.includes(file.type) && !isAllowedExtension) {
      setError('Định dạng không hỗ trợ. Vui lòng tải lên PDF, DOCX, TXT, RTF hoặc Hình ảnh.');
      return;
    }

    if (file.size > 10 * 1024 * 1024) {
      setError('Kích thước tệp quá lớn (Tối đa 10MB).');
      return;
    }
    onFileSelect(file);
  };

  return (
    <div className="w-full max-w-2xl mx-auto">
      <div
        onClick={() => !disabled && inputRef.current?.click()}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        className={`
          relative border-2 border-dashed rounded-2xl p-10 text-center cursor-pointer transition-all duration-300
          ${disabled ? 'opacity-50 cursor-not-allowed bg-gray-50 border-gray-200' : ''}
          ${isDragging 
            ? 'border-blue-500 bg-blue-50 scale-[1.02]' 
            : 'border-gray-300 hover:border-blue-400 hover:bg-gray-50 bg-white shadow-sm'
          }
        `}
      >
        <input
          ref={inputRef}
          type="file"
          accept=".pdf,.docx,.txt,.rtf,image/*"
          className="hidden"
          onChange={handleInputChange}
          disabled={disabled}
        />

        <div className="flex flex-col items-center justify-center gap-4">
          <div className={`p-4 rounded-full ${isDragging ? 'bg-blue-100' : 'bg-gray-100'}`}>
            <UploadCloud className={`w-10 h-10 ${isDragging ? 'text-blue-600' : 'text-gray-400'}`} />
          </div>
          <div className="space-y-2">
            <h3 className="text-xl font-semibold text-gray-700">
              {isDragging ? 'Thả tệp vào đây' : 'Nhấn để tải lên hoặc kéo thả tệp'}
            </h3>
            <p className="text-sm text-gray-500">Hỗ trợ PDF, DOCX, RTF hoặc <b>Dán ảnh (Ctrl+V)</b></p>
          </div>

          <div className="flex items-center gap-3">
              <div className="flex items-center gap-2 px-3 py-1.5 bg-blue-50 text-blue-600 rounded-lg border border-blue-100">
                <ClipboardPaste className="w-4 h-4" />
                <span className="text-xs font-bold uppercase tracking-wide">Hỗ trợ Dán</span>
              </div>
              <div className="flex items-center gap-2 px-3 py-1.5 bg-gray-50 rounded-lg border border-gray-100">
                <FileType className="w-4 h-4 text-gray-400" />
                <span className="text-xs text-gray-400 uppercase tracking-wide">AI Processing</span>
              </div>
          </div>
        </div>
      </div>

      {error && (
        <div className="mt-4 flex items-center gap-2 p-3 bg-red-50 text-red-600 rounded-lg border border-red-100 animate-fade-in">
          <AlertCircle className="w-5 h-5 shrink-0" />
          <span className="text-sm font-medium">{error}</span>
        </div>
      )}
    </div>
  );
};

import React, { useState, useCallback, useEffect } from 'react';
import { Header } from './components/Header';
import { FileUpload } from './components/FileUpload';
import { ProcessingView } from './components/ProcessingView';
import { ResultPreview } from './components/ResultPreview';
import { ImageCropper } from './components/ImageCropper';
import { AppStatus, ConversionResult, FileData, CroppedImage } from './types';
import { convertDocumentToLatex } from './services/geminiService';
import { AlertTriangle } from 'lucide-react';

const App: React.FC = () => {
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [currentFile, setCurrentFile] = useState<FileData | null>(null);
  const [result, setResult] = useState<ConversionResult | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [croppedImages, setCroppedImages] = useState<CroppedImage[]>([]);

  const processFile = async (fileData: FileData, images: CroppedImage[]) => {
    try {
      const htmlContent = await convertDocumentToLatex(fileData, images);

      setResult({
        content: htmlContent,
        fileName: fileData.name
      });
      setStatus(AppStatus.COMPLETE);
    } catch (error: any) {
      console.error(error);
      setStatus(AppStatus.ERROR);
      setErrorMessage(error.message || "Đã xảy ra lỗi không xác định trong quá trình xử lý.");
    }
  };

  const handleFileSelect = useCallback((file: File) => {
    setErrorMessage(null);
    setCroppedImages([]);

    const reader = new FileReader();
    reader.onload = async (e) => {
      const base64 = e.target?.result as string;
      const fileData: FileData = {
        name: file.name,
        size: file.size,
        type: file.type,
        base64: base64
      };

      setCurrentFile(fileData);

      // Both PDFs and Images now go through the Cropper stage
      if (file.type === 'application/pdf' || file.type.startsWith('image/')) {
        setStatus(AppStatus.CROP_SELECT);
      } else {
        setStatus(AppStatus.PROCESSING);
        processFile(fileData, []);
      }
    };
    reader.onerror = () => {
      setStatus(AppStatus.ERROR);
      setErrorMessage("Lỗi khi đọc file. Vui lòng thử lại.");
    };

    reader.readAsDataURL(file);
  }, []);

  // Handle Paste Event
  useEffect(() => {
    const handlePaste = (event: ClipboardEvent) => {
      if (status !== AppStatus.IDLE) return;

      const items = event.clipboardData?.items;
      if (!items) return;

      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const blob = items[i].getAsFile();
          if (blob) {
            const file = new File([blob], `pasted-image-${Date.now()}.png`, { type: blob.type });
            handleFileSelect(file);
            break;
          }
        }
      }
    };

    window.addEventListener('paste', handlePaste);
    return () => window.removeEventListener('paste', handlePaste);
  }, [status, handleFileSelect]);

  const handleCropComplete = (images: CroppedImage[]) => {
    setCroppedImages(images);
    if (currentFile) {
        setStatus(AppStatus.PROCESSING);
        processFile(currentFile, images);
    }
  };

  const handleCropCancel = () => {
      if (currentFile) {
          setStatus(AppStatus.PROCESSING);
          processFile(currentFile, []);
      }
  };

  const handleReset = () => {
    setStatus(AppStatus.IDLE);
    setCurrentFile(null);
    setResult(null);
    setErrorMessage(null);
    setCroppedImages([]);
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Header />

      <main className="flex-grow container mx-auto px-4 py-12 flex flex-col items-center justify-start gap-8 relative">

        {status === AppStatus.IDLE && (
          <div className="text-center max-w-2xl mx-auto space-y-4 mb-8">
            <h2 className="text-4xl font-extrabold text-gray-900 tracking-tight sm:text-5xl">
              Chuyển đổi <span className="text-blue-600">Tài liệu</span> sang <span className="text-blue-600">Word</span>
            </h2>
            <p className="text-lg text-gray-600 leading-relaxed">
              Giữ nguyên công thức toán học dưới dạng <strong>LaTeX code</strong> (ví dụ: $E=mc^2$). Hỗ trợ dán ảnh trực tiếp từ Clipboard.
            </p>
          </div>
        )}

        {status === AppStatus.IDLE && (
          <FileUpload onFileSelect={handleFileSelect} disabled={false} />
        )}

        {status === AppStatus.CROP_SELECT && currentFile && (
            <ImageCropper 
                fileData={currentFile} 
                onComplete={handleCropComplete}
                onCancel={handleCropCancel}
            />
        )}

        {(status === AppStatus.UPLOADING || status === AppStatus.PROCESSING) && currentFile && (
          <ProcessingView fileName={currentFile.name} isComplete={false} />
        )}

        {status === AppStatus.COMPLETE && result && (
          <ResultPreview result={result} onReset={handleReset} />
        )}

        {status === AppStatus.ERROR && (
          <div className="w-full max-w-lg bg-white rounded-xl shadow-lg border border-red-100 p-6 text-center space-y-4">
             <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto">
               <AlertTriangle className="w-8 h-8 text-red-600" />
             </div>
             <div>
               <h3 className="text-lg font-bold text-gray-900">Rất tiếc, đã xảy ra lỗi</h3>
               <p className="text-gray-600 mt-2">{errorMessage}</p>
             </div>
             <button 
                onClick={handleReset}
                className="px-6 py-2 bg-gray-900 text-white rounded-lg hover:bg-gray-800 transition-colors font-medium"
             >
               Thử lại
             </button>
          </div>
        )}

        {status === AppStatus.IDLE && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-5xl mt-12">
            {[
              { title: "Định dạng Word", desc: "Xuất ra file .doc với cấu trúc văn bản rõ ràng, dễ dàng chỉnh sửa trên Microsoft Word." },
              { title: "Toán học LaTeX", desc: "Các công thức không bị vỡ lỗi hình ảnh mà được giữ nguyên mã nguồn LaTeX (trong dấu $)." },
              { title: "Dán ảnh (Paste)", desc: "Bạn có thể dán trực tiếp ảnh chụp màn hình (Ctrl+V) để chọn vùng cần cắt hoặc OCR toàn bộ." }
            ].map((feature, idx) => (
              <div key={idx} className="bg-white p-6 rounded-xl border border-gray-100 shadow-sm hover:shadow-md transition-shadow">
                <h3 className="font-bold text-gray-900 mb-2">{feature.title}</h3>
                <p className="text-sm text-gray-500 leading-relaxed">{feature.desc}</p>
              </div>
            ))}
          </div>
        )}

      </main>

      <footer className="py-6 border-t border-gray-200 bg-white">
        <div className="container mx-auto px-4 text-center text-sm text-gray-500">
          © {new Date().getFullYear()} AI Document Converter. All rights reserved.
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';
import { ChevronLeft, ChevronRight, Crop, Check, X, Image as ImageIcon, ZoomIn, ZoomOut } from 'lucide-react';
import { CroppedImage, FileData } from '../types';

interface ImageCropperProps {
  fileData: FileData;
  onComplete: (images: CroppedImage[]) => void;
  onCancel: () => void;
}

// Internal resolution multiplier for sharp rendering
const RESOLUTION_FACTOR = 4;

export const ImageCropper: React.FC<ImageCropperProps> = ({ fileData, onComplete, onCancel }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [pdfDoc, setPdfDoc] = useState<any>(null);
  const [imageObj, setImageObj] = useState<HTMLImageElement | null>(null);
  const [pageNum, setPageNum] = useState(1);
  const [scale, setScale] = useState(1.0); // Visual zoom scale
  const [isDrawing, setIsDrawing] = useState(false);
  const [selection, setSelection] = useState<{ x: number; y: number; w: number; h: number } | null>(null);
  const [startPos, setStartPos] = useState<{ x: number; y: number }>({ x: 0, y: 0 });
  const [croppedImages, setCroppedImages] = useState<CroppedImage[]>([]);
  const [loading, setLoading] = useState(true);

  const isPdf = fileData.type === 'application/pdf';

  // Load Source (PDF or Image)
  useEffect(() => {
    const loadContent = async () => {
      setLoading(true);
      try {
        if (isPdf) {
          const loadingTask = (window as any).pdfjsLib.getDocument(fileData.base64);
          const pdf = await loadingTask.promise;
          setPdfDoc(pdf);
        } else if (fileData.type.startsWith('image/')) {
          const img = new Image();
          img.onload = () => {
            setImageObj(img);
            setLoading(false);
          };
          img.onerror = () => setLoading(false);
          img.src = fileData.base64;
        }
        if (isPdf) setLoading(false);
      } catch (error) {
        console.error("Error loading document", error);
        setLoading(false);
      }
    };

    loadContent();
  }, [fileData, isPdf]);

  // Render Page/Image
  useEffect(() => {
    if ((!pdfDoc && !imageObj) || !canvasRef.current) return;

    const render = async () => {
      const canvas = canvasRef.current!;
      const context = canvas.getContext('2d', { willReadFrequently: true })!;

      if (isPdf && pdfDoc) {
        const page = await pdfDoc.getPage(pageNum);
        const highResViewport = page.getViewport({ scale: scale * RESOLUTION_FACTOR });

        canvas.height = highResViewport.height;
        canvas.width = highResViewport.width;
        canvas.style.width = `${highResViewport.width / RESOLUTION_FACTOR}px`;
        canvas.style.height = `${highResViewport.height / RESOLUTION_FACTOR}px`;

        const renderContext = {
          canvasContext: context,
          viewport: highResViewport,
        };
        await page.render(renderContext).promise;
      } else if (imageObj) {
        const renderWidth = imageObj.width * scale * RESOLUTION_FACTOR;
        const renderHeight = imageObj.height * scale * RESOLUTION_FACTOR;

        canvas.width = renderWidth;
        canvas.height = renderHeight;
        canvas.style.width = `${renderWidth / RESOLUTION_FACTOR}px`;
        canvas.style.height = `${renderHeight / RESOLUTION_FACTOR}px`;

        context.drawImage(imageObj, 0, 0, renderWidth, renderHeight);
      }
    };

    render();
  }, [pdfDoc, imageObj, pageNum, scale, isPdf]);

  const getCoordinates = (e: React.MouseEvent) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    return {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top
    };
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDrawing(true);
    const pos = getCoordinates(e);
    setStartPos(pos);
    setSelection({ x: pos.x, y: pos.y, w: 0, h: 0 });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDrawing) return;
    const pos = getCoordinates(e);
    setSelection({
      x: Math.min(pos.x, startPos.x),
      y: Math.min(pos.y, startPos.y),
      w: Math.abs(pos.x - startPos.x),
      h: Math.abs(pos.y - startPos.y)
    });
  };

  const handleMouseUp = () => {
    setIsDrawing(false);
  };

  const saveCrop = () => {
    if (!selection || !canvasRef.current || selection.w < 5 || selection.h < 5) return;

    const sourceCanvas = canvasRef.current;
    const sourceX = selection.x * RESOLUTION_FACTOR;
    const sourceY = selection.y * RESOLUTION_FACTOR;
    const sourceW = selection.w * RESOLUTION_FACTOR;
    const sourceH = selection.h * RESOLUTION_FACTOR;

    const destCanvas = document.createElement('canvas');
    destCanvas.width = sourceW;
    destCanvas.height = sourceH;
    const ctx = destCanvas.getContext('2d')!;

    ctx.drawImage(
      sourceCanvas,
      sourceX, sourceY, sourceW, sourceH,
      0, 0, sourceW, sourceH
    );

    const base64 = destCanvas.toDataURL('image/png', 1.0);

    setCroppedImages([...croppedImages, {
      id: Date.now().toString(),
      base64,
      page: pageNum
    }]);
    setSelection(null);
  };

  const removeCrop = (id: string) => {
    setCroppedImages(croppedImages.filter(img => img.id !== id));
  };

  if (loading) return (
    <div className="fixed inset-0 z-[60] bg-white/80 backdrop-blur-sm flex items-center justify-center">
        <div className="text-center">
            <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
            <p className="text-gray-600 font-medium">Đang tải tài liệu...</p>
        </div>
    </div>
  );

  return (
    <div className="w-full h-full flex flex-col bg-gray-50 rounded-xl overflow-hidden border border-gray-200 shadow-xl fixed inset-0 z-50 md:relative md:h-[80vh]">
      {/* Header Toolbar */}
      <div className="bg-white border-b border-gray-200 p-3 flex items-center justify-between shadow-sm z-10">
        <div className="flex items-center gap-4">
          {isPdf && (
            <div className="flex items-center gap-1 bg-gray-100 rounded-lg p-1">
              <button 
                onClick={() => setPageNum(p => Math.max(1, p - 1))}
                disabled={pageNum <= 1}
                className="p-1 hover:bg-white rounded-md disabled:opacity-50 transition-colors"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>
              <span className="text-sm font-medium w-16 text-center">
                {pageNum} / {pdfDoc?.numPages || 1}
              </span>
              <button 
                onClick={() => setPageNum(p => Math.min(pdfDoc?.numPages || 1, p + 1))}
                disabled={pageNum >= (pdfDoc?.numPages || 1)}
                className="p-1 hover:bg-white rounded-md disabled:opacity-50 transition-colors"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
            </div>
          )}

          <div className="flex items-center gap-1 bg-gray-100 rounded-lg p-1">
            <button onClick={() => setScale(s => Math.max(0.3, s - 0.2))} className="p-1 hover:bg-white rounded-md">
              <ZoomOut className="w-5 h-5" />
            </button>
            <span className="text-sm font-medium w-12 text-center">{Math.round(scale * 100)}%</span>
            <button onClick={() => setScale(s => Math.min(3.0, s + 0.2))} className="p-1 hover:bg-white rounded-md">
              <ZoomIn className="w-5 h-5" />
            </button>
          </div>

          <span className="text-sm text-gray-500 hidden lg:inline">
            Kéo chuột để chọn vùng ảnh (hình vẽ, biểu đồ) cần trích xuất.
          </span>
        </div>

        <div className="flex items-center gap-2">
            <button 
                onClick={onCancel}
                className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg text-sm font-medium"
            >
                Hủy
            </button>
            <button 
                onClick={() => onComplete(croppedImages)}
                className="px-4 py-2 bg-blue-600 text-white hover:bg-blue-700 rounded-lg text-sm font-medium flex items-center gap-2 shadow-sm"
            >
                <Check className="w-4 h-4" />
                Dùng {croppedImages.length} ảnh đã chọn
            </button>
        </div>
      </div>

      <div className="flex flex-1 overflow-hidden">
        {/* Main Canvas Area */}
        <div className="flex-1 overflow-auto p-8 bg-gray-100 flex justify-center relative" ref={containerRef}>
          <div className="relative shadow-lg h-fit">
            <canvas
              ref={canvasRef}
              onMouseDown={handleMouseDown}
              onMouseMove={handleMouseMove}
              onMouseUp={handleMouseUp}
              onMouseLeave={handleMouseUp}
              className="cursor-crosshair bg-white"
            />
            {selection && (
              <div
                className="absolute border-2 border-blue-500 bg-blue-500/10 pointer-events-none"
                style={{
                  left: selection.x,
                  top: selection.y,
                  width: selection.w,
                  height: selection.h
                }}
              />
            )}

            {/* Context Menu for Selection */}
            {selection && selection.w > 10 && !isDrawing && (
              <div 
                className="absolute z-20"
                style={{ 
                    left: selection.x + selection.w - 40, 
                    top: selection.y + selection.h + 10 
                }}
              >
                <button 
                    onClick={saveCrop}
                    className="bg-blue-600 text-white p-2 rounded-full shadow-lg hover:bg-blue-700 hover:scale-110 transition-all"
                    title="Cắt vùng này"
                >
                    <Crop className="w-5 h-5" />
                </button>
              </div>
            )}
          </div>
        </div>

        {/* Sidebar - Cropped Images List */}
        <div className="w-64 bg-white border-l border-gray-200 flex flex-col">
           <div className="p-4 border-b border-gray-100">
             <h3 className="font-semibold text-gray-800 flex items-center gap-2">
               <ImageIcon className="w-4 h-4" />
               Ảnh đã cắt
             </h3>
             <p className="text-xs text-gray-500 mt-1">Sẽ được giữ nguyên trong file Word.</p>
           </div>

           <div className="flex-1 overflow-y-auto p-4 space-y-4">
              {croppedImages.length === 0 ? (
                  <div className="text-center text-gray-400 py-10 px-4">
                      <Crop className="w-10 h-10 mx-auto mb-2 opacity-20" />
                      <p className="text-sm">Chưa có ảnh nào được chọn. Hãy kéo chuột trên tài liệu để cắt.</p>
                  </div>
              ) : (
                  croppedImages.map((img, idx) => (
                      <div key={img.id} className="relative group bg-gray-50 rounded-lg border border-gray-200 p-2">
                          <div className="aspect-video w-full bg-white mb-2 overflow-hidden rounded border border-gray-100 flex items-center justify-center">
                              <img src={img.base64} alt={`Crop ${idx + 1}`} className="max-w-full max-h-24 object-contain" />
                          </div>
                          <div className="flex justify-between items-center">
                              <span className="text-xs font-medium text-gray-600">Ảnh {idx + 1}</span>
                              <button 
                                onClick={() => removeCrop(img.id)}
                                className="text-gray-400 hover:text-red-500 p-1"
                              >
                                  <X className="w-4 h-4" />
                              </button>
                          </div>
                      </div>
                  ))
              )}
           </div>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { FileData, CroppedImage } from "../types";

// Declare Mammoth globally as it's loaded via script tag
declare const mammoth: any;

// Initialize Gemini client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Helper to convert Base64 string to ArrayBuffer for Mammoth
 */
const base64ToArrayBuffer = (base64: string): ArrayBuffer => {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
};

/**
 * Helper to convert Base64 string to UTF-8 String for Text/RTF
 */
const base64ToString = (base64: string): string => {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return new TextDecoder().decode(bytes);
};

/**
 * Processes the file content based on type and asks Gemini for HTML with LaTeX math.
 */
export const convertDocumentToLatex = async (fileData: FileData, croppedImages: CroppedImage[] = []): Promise<string> => {
  try {
    const modelId = "gemini-2.5-flash";

    // Strip the data URL prefix if present (e.g., "data:application/pdf;base64,")
    const base64Content = fileData.base64.split(',')[1] || fileData.base64;

    let parts: any[] = [];
    let processingInstruction = "";

    // Determine how to handle the file based on type
    if (fileData.type === "application/pdf") {
      parts = [
        {
          inlineData: {
            mimeType: "application/pdf",
            data: base64Content
          }
        }
      ];
      processingInstruction = "Đây là một tài liệu PDF. Hãy nhìn vào cấu trúc hình ảnh để tái tạo lại văn bản.";

    } else if (fileData.type.startsWith("image/")) {
      // Direct image processing (for pasted images)
      parts = [
        {
          inlineData: {
            mimeType: fileData.type,
            data: base64Content
          }
        }
      ];
      processingInstruction = "Đây là một hình ảnh chứa văn bản và công thức toán. Hãy trích xuất và định dạng lại thành văn bản Word.";

    } else if (fileData.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document") {
      const arrayBuffer = base64ToArrayBuffer(base64Content);
      const result = await mammoth.convertToHtml({ arrayBuffer: arrayBuffer });
      const extractedHtml = result.value;

      parts = [{ text: extractedHtml }];
      processingInstruction = "Đây là mã HTML thô được trích xuất từ file DOCX. Hãy làm sạch nó, giữ nguyên cấu trúc bảng (table) và định dạng lại công thức toán.";

    } else if (fileData.type === "text/plain" || fileData.type.includes("rtf") || fileData.name.endsWith(".rtf")) {
      const textContent = base64ToString(base64Content);
      parts = [{ text: textContent }];
      processingInstruction = "Đây là nội dung văn bản thuần (hoặc RTF).";
    } else {
       throw new Error("Loại file không được hỗ trợ xử lý.");
    }

    // Add cropped images as additional context parts
    if (croppedImages.length > 0) {
        croppedImages.forEach((img, index) => {
             const imgBase64 = img.base64.split(',')[1];
             parts.push({
                 inlineData: {
                     mimeType: "image/png",
                     data: imgBase64
                 }
             });
        });
        processingInstruction += ` Tôi cũng đã đính kèm ${croppedImages.length} hình ảnh được cắt từ tài liệu này (theo thứ tự: Image 1, Image 2, ...).`;
    }

    const prompt = `
      Bạn là một chuyên gia chuyển đổi tài liệu kỹ thuật và toán học. ${processingInstruction}

      MỤC TIÊU: Tạo ra mã HTML sạch, tối ưu để hiển thị trong Microsoft Word (.doc).

      QUY TẮC 1: HÌNH ẢNH (QUAN TRỌNG)
      - Nếu có hình ảnh đính kèm (Image 1, Image 2...), hãy tìm vị trí logic để chèn thẻ [[IMAGE_X]].
      - Nếu đầu vào là một HÌNH ẢNH DUY NHẤT, hãy chuyển toàn bộ nội dung trong ảnh đó thành văn bản HTML.

      QUY TẮC 2: CÔNG THỨC TOÁN HỌC (LATEX)
      - GIỮ NGUYÊN mã LaTeX gốc trong dấu $. Ví dụ: $f(x) = x^2$.
      - Với các số hoặc chuỗi số (như $94; 82$), hãy bao quanh nội dung bằng dấu ngoặc nhọn: $\{94; 82\}$.
      - Với các điểm hình học liệt kê (như $G, K, C$), hãy bao quanh nội dung bằng dấu ngoặc nhọn: $\{G, K, C\}$.
      - Inline math: $...$
      - Block math: $$...$$
      - TUYỆT ĐỐI KHÔNG chuyển công thức thành ảnh hoặc unicode. Phải dùng LaTeX code.

      QUY TẮC 3: BẢNG BIỂU
      - Phải tái tạo cấu trúc bảng (<table>, <tr>, <td>).
      - Thẻ <table> PHẢI có thuộc tính: border="1" style="border-collapse: collapse; width: 100%; border: 1px solid black;"
      - Thẻ <td> PHẢI có style="border: 1px solid black; padding: 5px;"

      QUY TẮC 4: CẤU TRÚC VĂN BẢN
      - Sử dụng <h1>, <h2>, <p>. Giữ tiếng Việt có dấu.

      QUY TẮC 5: ĐỊNH DẠNG TRẮC NGHIỆM
      - CẤM TUYỆT ĐỐI dùng thẻ <ul>, <ol>, <li> cho các phương án A, B, C, D. Phải dùng thẻ <p> hoặc <div>.
      - Ví dụ: <p><b>A.</b> Nội dung</p>

      OUTPUT:
      - Chỉ trả về phần nội dung HTML bên trong thẻ <body>.
      - Không trả về markdown blocks (\`\`\`).
    `;

    parts.push({ text: prompt });

    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts: parts }
    });

    let text = response.text || "";
    let cleanHtml = text.replace(/```html/g, '').replace(/```/g, '').trim();

    // REGEX FIX 1: Wrap numbers and common separators (comma, semicolon, dots, space)
    // Matches: $94; 82$, $20,5$, $1.2$
    cleanHtml = cleanHtml.replace(/\$([0-9,;.\s]+)\$/g, (match, p1) => {
        const trimmed = p1.trim();
        if (!trimmed || trimmed.startsWith('{')) return match;
        return `$\{${trimmed}\}$`;
    });

    // REGEX FIX 2: Wrap geometric labels and point sequences
    // Matches: $A$, $ABCD$, $G, K, C$, $S.ABCD$
    // Supports: Letters, dots, commas, spaces
    cleanHtml = cleanHtml.replace(/\$([A-Za-z.,\s]+)\$/g, (match, p1) => {
        const trimmed = p1.trim();
        if (!trimmed || trimmed.startsWith('{')) return match;
        // Check if it's likely a label or point list (alphanumeric content)
        // If it contains things like +, =, ^, it's likely a real formula, don't force wrap everything
        if (/[^A-Za-z0-9.,\s]/.test(trimmed)) return match;
        return `$\{${trimmed}\}$`;
    });

    // Cleanup for quiz format failsafe
    cleanHtml = cleanHtml.replace(/<li>\s*([A-D]\.)/g, '<p><b>$1</b>');
    cleanHtml = cleanHtml.replace(/<\/li>/g, '</p>');

    if (croppedImages.length > 0) {
        croppedImages.forEach((img, index) => {
            const placeholder = `[[IMAGE_${index + 1}]]`;
            const imgTag = `<br/><div style="text-align:center; margin: 10px 0;"><img src="${img.base64}" alt="Image ${index + 1}" width="${img.base64.length > 100000 ? 500 : 'auto'}" style="max-width:100%; height:auto;" /></div><br/>`;
            cleanHtml = cleanHtml.split(placeholder).join(imgTag);
        });
    }

    return cleanHtml;
  } catch (error) {
    console.error("Gemini Conversion Error:", error);
    throw new Error("Không thể chuyển đổi tài liệu. Vui lòng thử lại.");
  }
};

