// Declare Mammoth globally as it's loaded via script tag
declare const mammoth: any;

// Initialize Gemini client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Helper to convert Base64 string to ArrayBuffer for Mammoth
 */
const base64ToArrayBuffer = (base64: string): ArrayBuffer => {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
};

/**
 * Helper to convert Base64 string to UTF-8 String for Text/RTF
 */
const base64ToString = (base64: string): string => {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return new TextDecoder().decode(bytes);
};

/**
 * Processes the file content based on type and asks Gemini for HTML with LaTeX math.
 */
export const convertDocumentToLatex = async (
  fileData: FileData, 
  croppedImages: CroppedImage[] = [],
  includeSolutions: boolean = false,
  generateSimilar: boolean = false,
  similarCount: number = 1,
  similarityLevel: SimilarityLevel = 'numbers'
): Promise<string> => {
  try {
    const modelId = "gemini-2.5-flash";
    const base64Content = fileData.base64.split(',')[1] || fileData.base64;

    let parts: any[] = [];
    let processingInstruction = "";

    if (fileData.type === "application/pdf") {
      parts = [{ inlineData: { mimeType: "application/pdf", data: base64Content } }];
      processingInstruction = "Đây là một tài liệu PDF chứa các bài tập.";
    } else if (fileData.type.startsWith("image/")) {
      parts = [{ inlineData: { mimeType: fileData.type, data: base64Content } }];
      processingInstruction = "Đây là một hình ảnh chứa nội dung học thuật.";
    } else if (fileData.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document") {
      const arrayBuffer = base64ToArrayBuffer(base64Content);
      const result = await mammoth.convertToHtml({ arrayBuffer: arrayBuffer });
      parts = [{ text: result.value }];
      processingInstruction = "Đây là mã HTML từ file DOCX.";
    } else if (fileData.type === "text/plain" || fileData.type.includes("rtf") || fileData.name.endsWith(".rtf")) {
      parts = [{ text: base64ToString(base64Content) }];
      processingInstruction = "Đây là nội dung văn bản thuần.";
    } else {
       throw new Error("Loại file không được hỗ trợ xử lý.");
    }

    if (croppedImages.length > 0) {
        croppedImages.forEach((img) => {
             parts.push({
                 inlineData: { mimeType: "image/png", data: img.base64.split(',')[1] }
             });
        });
        processingInstruction += ` Có thêm ${croppedImages.length} hình ảnh cắt từ tài liệu để minh họa nội dung.`;
    }

    const solutionPrompt = includeSolutions ? `
      NHIỆM VỤ GIẢI TOÁN: 
      - Sau mỗi câu hỏi gốc, hãy tạo thêm một phần có tiêu đề "Hướng dẫn giải chi tiết".
      - Trình bày lời giải từng bước, logic.
      - Sử dụng LaTeX triệt để.
      - Đặt lời giải trong thẻ <div style="background-color: #f0f7ff; padding: 15px; border-radius: 8px; border: 1px solid #bfdbfe; margin: 10px 0;">.
    ` : "";

    const similarPrompt = generateSimilar ? `
      NHIỆM VỤ TẠO BÀI TẬP TƯƠNG TỰ:
      - Với mỗi bài tập gốc được trích xuất, hãy tạo thêm ${similarCount} bài tập tương tự.
      - Mức độ tương tự: ${similarityLevel === 'numbers' ? 'Chỉ thay đổi các con số và giữ nguyên cấu trúc bài' : 'Dạng bài tương tự (cùng kiến thức nhưng cách đặt vấn đề khác đi)'}.
      - Các bài tập tương tự phải được trình bày ngay sau bài tập gốc (và sau lời giải bài gốc nếu có).
      - Đặt tiêu đề là "Bài tập tương tự ${similarCount > 1 ? '(Lần 1, 2...)' : ''}".
      - Sử dụng thẻ <div style="border: 2px dashed #e2e8f0; padding: 15px; border-radius: 12px; margin: 15px 0; background-color: #ffffff;"> để bao quanh các bài tập tương tự.
      - NẾU có yêu cầu giải chi tiết, hãy giải luôn cả các bài tập tương tự này.
    ` : "";

    const prompt = `
      Bạn là một chuyên gia chuyển đổi tài liệu học thuật. ${processingInstruction}

      MỤC TIÊU: Tạo ra mã HTML sạch cho Microsoft Word (.doc).

      QUY TẮC CÔNG THỨC TOÁN (QUAN TRỌNG):
      - Công thức luôn nằm trong dấu $. Ví dụ: $x^2$.
      - Với chuỗi số hoặc điểm hình học liệt kê (G, K, C): Bao quanh nội dung bằng dấu ngoặc nhọn trong math mode: $\{G, K, C\}$.
      - Với các mặt phẳng trong ngoặc đơn (EFGH), (IJKL): VIẾT THÀNH CÁC KHỐI MATH RIÊNG BIỆT. DẤU PHẨY NẰM NGOÀI.
        Ví dụ: $(EFGH)$, $(IJKL)$.
      - Không được dùng $\{,\}$ hay $\{;\}$ trong math mode một cách vô lý.

      ${solutionPrompt}
      ${similarPrompt}

      CẤU TRÚC:
      - Sử dụng <table>, <tr>, <td> cho bảng biểu.
      - Chèn thẻ [[IMAGE_X]] vào vị trí hình vẽ/biểu đồ tương ứng.

      OUTPUT: Chỉ trả về nội dung bên trong thẻ <body>. Không dùng markdown code block.
    `;

    parts.push({ text: prompt });

    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts: parts }
    });

    let text = response.text || "";
    let cleanHtml = text.replace(/```html/g, '').replace(/```/g, '').trim();

    // LaTeX Post-processing
    cleanHtml = cleanHtml.replace(/\$([0-9,;.\s]+)\$/g, (m, p1) => {
        const t = p1.trim();
        if (!t || t.startsWith('{') || !/[0-9]/.test(t)) return m;
        return `$\{${t}\}$`;
    });
    cleanHtml = cleanHtml.replace(/\$([A-Za-z.,\s]+)\$/g, (m, p1) => {
        const t = p1.trim();
        if (!t || t.startsWith('{') || !/[A-Za-z]/.test(t) || /^[.,\s]+$/.test(t)) return m;
        return `$\{${t}\}$`;
    });

    if (croppedImages.length > 0) {
        croppedImages.forEach((img, index) => {
            const placeholder = `[[IMAGE_${index + 1}]]`;
            const imgTag = `<br/><div style="text-align:center; margin: 10px 0;"><img src="${img.base64}" alt="Image ${index + 1}" style="max-width:100%; height:auto;" /></div><br/>`;
            cleanHtml = cleanHtml.split(placeholder).join(imgTag);
        });
    }

    return cleanHtml;
  } catch (error) {
    console.error("Gemini Conversion Error:", error);
    throw new Error("Không thể xử lý tài liệu. Vui lòng thử lại.");
  }
};

