import { GoogleGenAI } from "@google/genai";
import { FileData, CroppedImage, SimilarityLevel, MathFormat } from "../types";

// Declare Mammoth globally as it's loaded via script tag
declare const mammoth: any;

// Initialize Gemini client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const base64ToArrayBuffer = (base64: string): ArrayBuffer => {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
};

const base64ToString = (base64: string): string => {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return new TextDecoder().decode(bytes);
};

/**
 * Main conversion service
 */
export const convertDocument = async (
  fileData: FileData, 
  croppedImages: CroppedImage[] = [],
  includeSolutions: boolean = false,
  generateSimilar: boolean = false,
  similarCount: number = 1,
  similarityLevel: SimilarityLevel = 'numbers',
  mathFormat: MathFormat = 'latex'
): Promise<string> => {
  try {
    const modelId = "gemini-2.5-flash";
    const base64Content = fileData.base64.split(',')[1] || fileData.base64;

    let parts: any[] = [];
    let processingInstruction = "";

    if (fileData.type === "application/pdf") {
      parts = [{ inlineData: { mimeType: "application/pdf", data: base64Content } }];
      processingInstruction = "Đây là tài liệu PDF.";
    } else if (fileData.type.startsWith("image/")) {
      parts = [{ inlineData: { mimeType: fileData.type, data: base64Content } }];
      processingInstruction = "Đây là hình ảnh.";
    } else if (fileData.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document") {
      const arrayBuffer = base64ToArrayBuffer(base64Content);
      const result = await mammoth.convertToHtml({ arrayBuffer: arrayBuffer });
      parts = [{ text: result.value }];
      processingInstruction = "Đây là mã HTML từ DOCX.";
    } else {
      parts = [{ text: base64ToString(base64Content) }];
      processingInstruction = "Đây là văn bản thuần/RTF.";
    }

    if (croppedImages.length > 0) {
        croppedImages.forEach((img) => {
             parts.push({ inlineData: { mimeType: "image/png", data: img.base64.split(',')[1] } });
        });
    }

    // Define Math instructions based on format
    const mathInstructions = mathFormat === 'latex' 
      ? `Sử dụng định dạng LaTeX trong dấu $. Ví dụ: $x^2 + y^2 = r^2$. 
         Với các mặt phẳng, viết riêng biệt: $(ABC)$, $(SBC)$.
         Với điểm liệt kê: $\{A, B, C\}$.`
      : `Sử dụng định dạng MathML (<math>...</math>) cho tất cả các công thức toán học. 
         Đảm bảo mã MathML chuẩn để Microsoft Word có thể nhận diện thành đối tượng Equation khi mở file. 
         TUYỆT ĐỐI KHÔNG dùng dấu $ hay LaTeX.`;

    const solutionPrompt = includeSolutions ? `
      NHIỆM VỤ GIẢI TOÁN: Sau mỗi câu hỏi, tạo phần "Hướng dẫn giải chi tiết" trong thẻ <div> màu xanh nhạt.
    ` : "";

    const similarPrompt = generateSimilar ? `
      NHIỆM VỤ TẠO BÀI TẬP: Tạo ${similarCount} bài tập tương tự (mức độ: ${similarityLevel}).
      Đặt trong thẻ <div> có viền đứt (dashed).
    ` : "";

    const prompt = `
      Bạn là chuyên gia chuyển đổi tài liệu học thuật sang HTML cho Word.
      ${processingInstruction}

      YÊU CẦU ĐỊNH DẠNG TOÁN HỌC:
      ${mathInstructions}

      ${solutionPrompt}
      ${similarPrompt}

      LƯU Ý: 
      - Tái tạo bảng bằng thẻ <table>.
      - Chèn [[IMAGE_X]] cho hình ảnh.
      - Output chỉ trả về nội dung bên trong <body>. Không markdown.
    `;

    parts.push({ text: prompt });

    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts: parts }
    });

    let text = response.text || "";
    let cleanHtml = text.replace(/```html/g, '').replace(/```/g, '').trim();

    // Post-processing only for LaTeX format
    if (mathFormat === 'latex') {
      cleanHtml = cleanHtml.replace(/\$([0-9,;.\s]+)\$/g, (m, p1) => {
          const t = p1.trim();
          if (!t || t.startsWith('{') || !/[0-9]/.test(t)) return m;
          return `$\{${t}\}$`;
      });
      cleanHtml = cleanHtml.replace(/\$([A-Za-z.,\s]+)\$/g, (m, p1) => {
          const t = p1.trim();
          if (!t || t.startsWith('{') || !/[A-Za-z]/.test(t) || /^[.,\s]+$/.test(t)) return m;
          return `$\{${t}\}$`;
      });
    }

    if (croppedImages.length > 0) {
        croppedImages.forEach((img, index) => {
            const placeholder = `[[IMAGE_${index + 1}]]`;
            const imgTag = `<br/><div style="text-align:center;"><img src="${img.base64}" style="max-width:100%;" /></div><br/>`;
            cleanHtml = cleanHtml.split(placeholder).join(imgTag);
        });
    }

    return cleanHtml;
  } catch (error) {
    console.error("Gemini Conversion Error:", error);
    throw new Error("Lỗi xử lý tài liệu.");
  }
};

import React, { useState, useCallback, useEffect } from 'react';
import { Header } from './components/Header';
import { FileUpload } from './components/FileUpload';
import { ProcessingView } from './components/ProcessingView';
import { ResultPreview } from './components/ResultPreview';
import { ImageCropper } from './components/ImageCropper';
import { AppStatus, ConversionResult, FileData, CroppedImage, SimilarityLevel, MathFormat } from './types';
import { convertDocument } from './services/geminiService';
import { AlertTriangle, BrainCircuit, Sparkles, Layers, Settings2, PlusCircle, FunctionSquare, Binary } from 'lucide-react';

const App: React.FC = () => {
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [currentFile, setCurrentFile] = useState<FileData | null>(null);
  const [result, setResult] = useState<ConversionResult | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [croppedImages, setCroppedImages] = useState<CroppedImage[]>([]);

  // Feature states
  const [includeSolutions, setIncludeSolutions] = useState<boolean>(false);
  const [generateSimilar, setGenerateSimilar] = useState<boolean>(false);
  const [similarCount, setSimilarCount] = useState<number>(1);
  const [similarityLevel, setSimilarityLevel] = useState<SimilarityLevel>('numbers');
  const [mathFormat, setMathFormat] = useState<MathFormat>('latex');

  const processFile = async (fileData: FileData, images: CroppedImage[]) => {
    try {
      const htmlContent = await convertDocument(
        fileData, 
        images, 
        includeSolutions, 
        generateSimilar, 
        similarCount, 
        similarityLevel,
        mathFormat
      );

      setResult({
        content: htmlContent,
        fileName: fileData.name
      });
      setStatus(AppStatus.COMPLETE);
    } catch (error: any) {
      console.error(error);
      setStatus(AppStatus.ERROR);
      setErrorMessage(error.message || "Đã xảy ra lỗi.");
    }
  };

  const handleFileSelect = useCallback((file: File) => {
    setErrorMessage(null);
    setCroppedImages([]);
    const reader = new FileReader();
    reader.onload = async (e) => {
      const base64 = e.target?.result as string;
      const fileData: FileData = {
        name: file.name, size: file.size, type: file.type, base64: base64
      };
      setCurrentFile(fileData);
      if (file.type === 'application/pdf' || file.type.startsWith('image/')) {
        setStatus(AppStatus.CROP_SELECT);
      } else {
        setStatus(AppStatus.PROCESSING);
        processFile(fileData, []);
      }
    };
    reader.readAsDataURL(file);
  }, [includeSolutions, generateSimilar, similarCount, similarityLevel, mathFormat]);

  useEffect(() => {
    const handlePaste = (event: ClipboardEvent) => {
      if (status !== AppStatus.IDLE) return;
      const items = event.clipboardData?.items;
      if (!items) return;
      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const blob = items[i].getAsFile();
          if (blob) {
            const file = new File([blob], `pasted-${Date.now()}.png`, { type: blob.type });
            handleFileSelect(file);
            break;
          }
        }
      }
    };
    window.addEventListener('paste', handlePaste);
    return () => window.removeEventListener('paste', handlePaste);
  }, [status, handleFileSelect]);

  const handleCropComplete = (images: CroppedImage[]) => {
    setCroppedImages(images);
    if (currentFile) {
        setStatus(AppStatus.PROCESSING);
        processFile(currentFile, images);
    }
  };

  const handleCropCancel = () => {
      if (currentFile) {
          setStatus(AppStatus.PROCESSING);
          processFile(currentFile, []);
      }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Header />

      <main className="flex-grow container mx-auto px-4 py-8 flex flex-col items-center justify-start gap-6 relative">

        {status === AppStatus.IDLE && (
          <div className="text-center max-w-2xl mx-auto mb-2">
            <h2 className="text-4xl font-extrabold text-gray-900 tracking-tight mb-2">
              Chuyển đổi <span className="text-blue-600">Thông minh</span>
            </h2>
            <p className="text-gray-600">Trích xuất văn bản & hỗ trợ Equation/LaTeX cho Microsoft Word.</p>
          </div>
        )}

        {status === AppStatus.IDLE && (
          <div className="w-full max-w-2xl mx-auto space-y-4">

            {/* Primary Controls Row */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              <div className={`p-4 rounded-xl border-2 transition-all flex items-center justify-between ${includeSolutions ? 'bg-blue-50 border-blue-200' : 'bg-white border-gray-100 shadow-sm'}`}>
                <div className="flex items-center gap-3">
                  <BrainCircuit className={`w-5 h-5 ${includeSolutions ? 'text-blue-600' : 'text-gray-400'}`} />
                  <div>
                    <h4 className="font-bold text-gray-900 text-sm">Giải toán chi tiết</h4>
                    <p className="text-[10px] text-gray-500">Kèm lời giải từng bước.</p>
                  </div>
                </div>
                <button onClick={() => setIncludeSolutions(!includeSolutions)} className={`h-5 w-9 rounded-full relative transition-colors ${includeSolutions ? 'bg-blue-600' : 'bg-gray-200'}`}>
                  <span className={`absolute top-1 left-1 h-3 w-3 rounded-full bg-white transition-transform ${includeSolutions ? 'translate-x-4' : ''}`} />
                </button>
              </div>

              <div className={`p-4 rounded-xl border-2 transition-all flex items-center justify-between ${generateSimilar ? 'bg-indigo-50 border-indigo-200' : 'bg-white border-gray-100 shadow-sm'}`}>
                <div className="flex items-center gap-3">
                  <Layers className={`w-5 h-5 ${generateSimilar ? 'text-indigo-600' : 'text-gray-400'}`} />
                  <div>
                    <h4 className="font-bold text-gray-900 text-sm">Bài tập tương tự</h4>
                    <p className="text-[10px] text-gray-500">Sinh thêm bài toán mới.</p>
                  </div>
                </div>
                <button onClick={() => setGenerateSimilar(!generateSimilar)} className={`h-5 w-9 rounded-full relative transition-colors ${generateSimilar ? 'bg-indigo-600' : 'bg-gray-200'}`}>
                  <span className={`absolute top-1 left-1 h-3 w-3 rounded-full bg-white transition-transform ${generateSimilar ? 'translate-x-4' : ''}`} />
                </button>
              </div>
            </div>

            {/* Math Format & Advanced Settings */}
            <div className="bg-white p-5 rounded-xl border border-gray-200 shadow-sm space-y-5">

              {/* Math Format Selector */}
              <div>
                <label className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 block">Định dạng Công thức</label>
                <div className="grid grid-cols-2 gap-2 bg-gray-50 p-1.5 rounded-lg border border-gray-100">
                  <button 
                    onClick={() => setMathFormat('latex')}
                    className={`flex items-center justify-center gap-2 py-2.5 rounded-md text-xs font-bold transition-all ${mathFormat === 'latex' ? 'bg-white text-blue-600 shadow-sm border border-blue-100' : 'text-gray-400 hover:text-gray-600'}`}
                  >
                    <Binary className="w-4 h-4" />
                    LaTeX ($...$)
                  </button>
                  <button 
                    onClick={() => setMathFormat('equation')}
                    className={`flex items-center justify-center gap-2 py-2.5 rounded-md text-xs font-bold transition-all ${mathFormat === 'equation' ? 'bg-white text-blue-600 shadow-sm border border-blue-100' : 'text-gray-400 hover:text-gray-600'}`}
                  >
                    <FunctionSquare className="w-4 h-4" />
                    Word Equation
                  </button>
                </div>
                <p className="text-[10px] text-gray-400 mt-2 italic">
                  {mathFormat === 'latex' ? "* Phù hợp để copy mã nguồn. Dùng ký hiệu $." : "* Công thức có thể chỉnh sửa trực tiếp trong Word (Equation)."}
                </p>
              </div>

              {/* Similar Settings */}
              {generateSimilar && (
                <div className="pt-4 border-t border-gray-100 animate-fade-in space-y-4">
                  <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-gray-600">Số lượng ({similarCount}):</label>
                      <input type="range" min="1" max="5" value={similarCount} onChange={(e) => setSimilarCount(parseInt(e.target.value))} className="w-full accent-indigo-600" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-gray-600">Mức độ:</label>
                      <div className="flex bg-gray-100 p-1 rounded-md text-[10px]">
                        <button onClick={() => setSimilarityLevel('numbers')} className={`flex-1 py-1 rounded ${similarityLevel === 'numbers' ? 'bg-white shadow-sm text-indigo-600' : 'text-gray-400'}`}>Chỉ đổi số</button>
                        <button onClick={() => setSimilarityLevel('type')} className={`flex-1 py-1 rounded ${similarityLevel === 'type' ? 'bg-white shadow-sm text-indigo-600' : 'text-gray-400'}`}>Dạng bài</button>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>

            <FileUpload onFileSelect={handleFileSelect} disabled={false} />
          </div>
        )}

        {status === AppStatus.CROP_SELECT && currentFile && (
            <ImageCropper fileData={currentFile} onComplete={handleCropComplete} onCancel={handleCropCancel} />
        )}

        {(status === AppStatus.PROCESSING) && currentFile && (
          <ProcessingView fileName={currentFile.name} isComplete={false} />
        )}

        {status === AppStatus.COMPLETE && result && (
          <ResultPreview result={result} onReset={() => setStatus(AppStatus.IDLE)} />
        )}

        {status === AppStatus.ERROR && (
          <div className="bg-white rounded-xl shadow-lg border border-red-100 p-8 text-center max-w-md mx-auto">
             <AlertTriangle className="w-12 h-12 text-red-500 mx-auto mb-4" />
             <h3 className="text-lg font-bold text-gray-900">Lỗi xử lý</h3>
             <p className="text-gray-600 mt-2 mb-6">{errorMessage}</p>
             <button onClick={() => setStatus(AppStatus.IDLE)} className="px-8 py-2 bg-gray-900 text-white rounded-lg">Thử lại</button>
          </div>
        )}
      </main>

      <footer className="py-6 border-t border-gray-200 bg-white mt-auto text-center text-xs text-gray-400">
        © {new Date().getFullYear()} AI Document Hub. MathML & LaTeX Supported.
      </footer>
    </div>
  );
};

