import React, { useEffect, useRef, useState } from 'react';
import { ChevronLeft, ChevronRight, Crop, Check, X, Image as ImageIcon, ZoomIn, ZoomOut, MousePointer2, Trash2 } from 'lucide-react';
import { CroppedImage, FileData } from '../types';

interface ImageCropperProps {
  fileData: FileData;
  externalCrops?: CroppedImage[];
  onComplete: (images: CroppedImage[]) => void;
  onCancel: () => void;
}

const RESOLUTION_FACTOR = 4;

export const ImageCropper: React.FC<ImageCropperProps> = ({ fileData, externalCrops = [], onComplete, onCancel }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [pdfDoc, setPdfDoc] = useState<any>(null);
  const [imageObj, setImageObj] = useState<HTMLImageElement | null>(null);
  const [pageNum, setPageNum] = useState(1);
  const [scale, setScale] = useState(1.0);
  const [isDrawing, setIsDrawing] = useState(false);
  const [selection, setSelection] = useState<{ x: number; y: number; w: number; h: number } | null>(null);
  const [startPos, setStartPos] = useState<{ x: number; y: number }>({ x: 0, y: 0 });
  const [croppedImages, setCroppedImages] = useState<CroppedImage[]>([]);
  const [loading, setLoading] = useState(true);

  const isPdf = fileData.type === 'application/pdf';

  // Sync external crops (like from paste)
  useEffect(() => {
    if (externalCrops.length > 0) {
      setCroppedImages(prev => {
        const existingIds = new Set(prev.map(c => c.id));
        const newOnes = externalCrops.filter(c => !existingIds.has(c.id));
        return [...prev, ...newOnes];
      });
    }
  }, [externalCrops]);

  useEffect(() => {
    const loadContent = async () => {
      setLoading(true);
      try {
        if (isPdf) {
          const loadingTask = (window as any).pdfjsLib.getDocument(fileData.base64);
          const pdf = await loadingTask.promise;
          setPdfDoc(pdf);
        } else if (fileData.type.startsWith('image/')) {
          const img = new Image();
          img.onload = () => {
            setImageObj(img);
            setLoading(false);
          };
          img.src = fileData.base64;
        }
        if (isPdf) setLoading(false);
      } catch (error) {
        setLoading(false);
      }
    };
    loadContent();
  }, [fileData, isPdf]);

  useEffect(() => {
    if ((!pdfDoc && !imageObj) || !canvasRef.current) return;
    const render = async () => {
      const canvas = canvasRef.current!;
      const context = canvas.getContext('2d', { willReadFrequently: true })!;
      if (isPdf && pdfDoc) {
        const page = await pdfDoc.getPage(pageNum);
        const highResViewport = page.getViewport({ scale: scale * RESOLUTION_FACTOR });
        canvas.height = highResViewport.height;
        canvas.width = highResViewport.width;
        canvas.style.width = `${highResViewport.width / RESOLUTION_FACTOR}px`;
        canvas.style.height = `${highResViewport.height / RESOLUTION_FACTOR}px`;
        await page.render({ canvasContext: context, viewport: highResViewport }).promise;
      } else if (imageObj) {
        const renderWidth = imageObj.width * scale * RESOLUTION_FACTOR;
        const renderHeight = imageObj.height * scale * RESOLUTION_FACTOR;
        canvas.width = renderWidth;
        canvas.height = renderHeight;
        canvas.style.width = `${renderWidth / RESOLUTION_FACTOR}px`;
        canvas.style.height = `${renderHeight / RESOLUTION_FACTOR}px`;
        context.drawImage(imageObj, 0, 0, renderWidth, renderHeight);
      }
    };
    render();
  }, [pdfDoc, imageObj, pageNum, scale, isPdf]);

  const getCoordinates = (e: React.MouseEvent) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    return { x: e.clientX - rect.left, y: e.clientY - rect.top };
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDrawing(true);
    const pos = getCoordinates(e);
    setStartPos(pos);
    setSelection({ x: pos.x, y: pos.y, w: 0, h: 0 });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDrawing) return;
    const pos = getCoordinates(e);
    setSelection({
      x: Math.min(pos.x, startPos.x),
      y: Math.min(pos.y, startPos.y),
      w: Math.abs(pos.x - startPos.x),
      h: Math.abs(pos.y - startPos.y)
    });
  };

  const saveCrop = () => {
    if (!selection || !canvasRef.current || selection.w < 5) return;
    const sourceCanvas = canvasRef.current;
    const sourceX = selection.x * RESOLUTION_FACTOR;
    const sourceY = selection.y * RESOLUTION_FACTOR;
    const sourceW = selection.w * RESOLUTION_FACTOR;
    const sourceH = selection.h * RESOLUTION_FACTOR;
    const destCanvas = document.createElement('canvas');
    destCanvas.width = sourceW;
    destCanvas.height = sourceH;
    const ctx = destCanvas.getContext('2d')!;
    ctx.drawImage(sourceCanvas, sourceX, sourceY, sourceW, sourceH, 0, 0, sourceW, sourceH);
    setCroppedImages([...croppedImages, { id: Date.now().toString(), base64: destCanvas.toDataURL('image/png'), page: pageNum }]);
    setSelection(null);
  };

  if (loading) return <div className="fixed inset-0 bg-white flex items-center justify-center z-[100]"><p>Đang tải tài liệu...</p></div>;

  return (
    <div className="w-full h-full flex flex-col bg-gray-50 fixed inset-0 z-50 md:relative md:h-[80vh] border border-gray-200 shadow-2xl rounded-xl overflow-hidden">
      <div className="bg-white border-b border-gray-200 p-3 flex items-center justify-between z-10">
        <div className="flex items-center gap-3">
          {isPdf && (
            <div className="flex items-center gap-1 bg-gray-100 rounded-lg p-1">
              <button onClick={() => setPageNum(p => Math.max(1, p - 1))} disabled={pageNum <= 1} className="p-1 disabled:opacity-30"><ChevronLeft className="w-5 h-5"/></button>
              <span className="text-xs font-bold w-12 text-center">{pageNum}/{pdfDoc?.numPages}</span>
              <button onClick={() => setPageNum(p => Math.min(pdfDoc?.numPages, p + 1))} disabled={pageNum >= pdfDoc?.numPages} className="p-1 disabled:opacity-30"><ChevronRight className="w-5 h-5"/></button>
            </div>
          )}
          <div className="flex items-center gap-1 bg-gray-100 rounded-lg p-1">
            <button onClick={() => setScale(s => Math.max(0.3, s - 0.2))} className="p-1"><ZoomOut className="w-4 h-4"/></button>
            <span className="text-xs font-bold w-10 text-center">{Math.round(scale * 100)}%</span>
            <button onClick={() => setScale(s => Math.min(3, s + 0.2))} className="p-1"><ZoomIn className="w-4 h-4"/></button>
          </div>
          <div className="hidden lg:flex items-center gap-2 px-3 py-1 bg-blue-50 text-blue-600 rounded-full border border-blue-100 text-[10px] font-bold uppercase tracking-wide">
            <MousePointer2 className="w-3 h-3" />
            Kéo chuột để cắt hoặc nhấn Ctrl+V để dán ảnh mới
          </div>
        </div>
        <div className="flex items-center gap-2">
            <button 
              onClick={onCancel} 
              className="px-3 py-1.5 text-xs font-bold text-gray-500 hover:text-red-600 flex items-center gap-1.5 transition-colors"
              title="Xóa tất cả ảnh đã chọn"
            >
              <Trash2 className="w-3.5 h-3.5" />
              XÓA ẢNH
            </button>
            <button onClick={() => onComplete(croppedImages)} className="px-4 py-2 bg-blue-600 text-white rounded-lg text-xs font-bold flex items-center gap-2 hover:bg-blue-700 transition-all shadow-sm">
                <Check className="w-4 h-4" /> DÙNG {croppedImages.length} ẢNH
            </button>
        </div>
      </div>

      <div className="flex flex-1 overflow-hidden">
        <div className="flex-1 overflow-auto p-8 bg-gray-200 flex justify-center relative">
          <div className="relative shadow-2xl h-fit">
            <canvas ref={canvasRef} onMouseDown={handleMouseDown} onMouseMove={handleMouseMove} onMouseUp={() => setIsDrawing(false)} className="cursor-crosshair bg-white" />
            {selection && <div className="absolute border-2 border-blue-500 bg-blue-500/10 pointer-events-none" style={{ left: selection.x, top: selection.y, width: selection.w, height: selection.h }} />}
            {selection && selection.w > 10 && !isDrawing && (
              <button onClick={saveCrop} className="absolute z-20 bg-blue-600 text-white p-2 rounded-full shadow-lg hover:scale-110 transition-all" style={{ left: selection.x + selection.w - 15, top: selection.y + selection.h - 15 }}><Crop className="w-4 h-4" /></button>
            )}
          </div>
        </div>

        <div className="w-64 bg-white border-l border-gray-200 flex flex-col">
           <div className="p-4 border-b border-gray-100 bg-gray-50">
             <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2"><ImageIcon className="w-3 h-3" /> ẢNH ĐÃ CHỌN</h3>
           </div>
           <div className="flex-1 overflow-y-auto p-4 space-y-4">
              {croppedImages.length === 0 ? (
                  <div className="text-center text-gray-300 py-10">
                    <Crop className="w-10 h-10 mx-auto mb-2 opacity-10" />
                    <p className="text-[10px] uppercase font-bold tracking-wider">Chưa có ảnh nào</p>
                  </div>
              ) : (
                  croppedImages.map((img, idx) => (
                      <div key={img.id} className="relative group bg-white rounded border border-gray-200 p-1 shadow-sm overflow-hidden">
                          <img src={img.base64} className="w-full h-auto max-h-32 object-contain bg-gray-50 rounded" />
                          <div className="mt-1 flex justify-between items-center px-1 py-1 bg-gray-50 border-t border-gray-100">
                              <span className="text-[10px] font-bold text-gray-400">ẢNH {idx + 1}</span>
                              <button 
                                onClick={() => setCroppedImages(croppedImages.filter(c => c.id !== img.id))} 
                                className="flex items-center gap-1 text-[10px] font-bold text-red-500 hover:text-red-700 transition-colors"
                              >
                                <X className="w-3 h-3" />
                                XÓA
                              </button>
                          </div>
                          {img.page === 0 && <span className="absolute top-1 right-1 bg-amber-500 text-white text-[8px] px-1 rounded shadow-sm">PASTED</span>}
                      </div>
                  ))
              )}
           </div>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { FileData, CroppedImage, SimilarityLevel, MathFormat } from "../types";

// Declare Mammoth globally as it's loaded via script tag
declare const mammoth: any;

// Initialize Gemini client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const base64ToArrayBuffer = (base64: string): ArrayBuffer => {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
};

const base64ToString = (base64: string): string => {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return new TextDecoder().decode(bytes);
};

/**
 * Main conversion service
 */
export const convertDocument = async (
  fileData: FileData, 
  croppedImages: CroppedImage[] = [],
  includeSolutions: boolean = false,
  generateSimilar: boolean = false,
  similarCount: number = 1,
  similarityLevel: SimilarityLevel = 'numbers',
  mathFormat: MathFormat = 'latex'
): Promise<string> => {
  try {
    const modelId = "gemini-2.5-flash";
    const base64Content = fileData.base64.split(',')[1] || fileData.base64;

    let parts: any[] = [];
    let processingInstruction = "";

    // Gửi tài liệu gốc trước
    if (fileData.type === "application/pdf") {
      parts.push({ inlineData: { mimeType: "application/pdf", data: base64Content } });
      processingInstruction = "Đây là tài liệu gốc (PDF).";
    } else if (fileData.type.startsWith("image/")) {
      parts.push({ inlineData: { mimeType: fileData.type, data: base64Content } });
      processingInstruction = "Đây là hình ảnh gốc.";
    } else if (fileData.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document") {
      const arrayBuffer = base64ToArrayBuffer(base64Content);
      const result = await mammoth.convertToHtml({ arrayBuffer: arrayBuffer });
      parts.push({ text: result.value });
      processingInstruction = "Đây là mã HTML từ DOCX gốc.";
    } else {
      parts.push({ text: base64ToString(base64Content) });
      processingInstruction = "Đây là văn bản gốc.";
    }

    // Gửi các ảnh cắt kèm metadata
    if (croppedImages.length > 0) {
        croppedImages.forEach((img, idx) => {
             parts.push({ 
               inlineData: { 
                 mimeType: "image/png", 
                 data: img.base64.split(',')[1] 
               } 
             });
        });
        processingInstruction += ` Kèm theo ${croppedImages.length} ảnh cắt chi tiết (như hình vẽ, biểu đồ) được trích xuất từ tài liệu này.`;
    }

    const mathInstructions = mathFormat === 'latex' 
      ? `Sử dụng định dạng LaTeX trong dấu $. 
         QUY TẮC ĐẶC BIỆT: Với các mã lớp hoặc định danh ngắn như 7A, 7B, 10C, hãy bọc chúng trong dấu ngoặc nhọn bên trong dấu đô la, ví dụ: $\{7A\}$, $\{7B\}$.
         Với điểm/mặt phẳng: $\{A, B, C\}$, $(ABC)$.`
      : `Sử dụng định dạng MathML (<math>...</math>) cho mọi công thức. Tuyệt đối không dùng LaTeX.`;

    const solutionPrompt = includeSolutions ? `
      NHIỆM VỤ GIẢI TOÁN: Giải chi tiết từng câu hỏi ngay sau đề bài gốc. Sử dụng thẻ <div style="background-color: #f0f7ff; padding: 12px; margin: 8px 0; border-left: 4px solid #3b82f6;">.
    ` : "";

    const similarPrompt = generateSimilar ? `
      NHIỆM VỤ BÀI TẬP TƯƠNG TỰ: Tạo ${similarCount} bài tương tự (${similarityLevel === 'numbers' ? 'chỉ đổi số' : 'đổi dạng tương đương'}). Đặt trong <div style="border: 1px dashed #cbd5e1; padding: 12px; margin: 8px 0;">.
    ` : "";

    const prompt = `
      Bạn là chuyên gia chuyển đổi tài liệu học thuật.

      YÊU CẦU QUAN TRỌNG VỀ VỊ TRÍ HÌNH ẢNH:
      1. Bạn đã nhận được một tài liệu gốc và ${croppedImages.length} ảnh cắt nhỏ.
      2. Các ảnh cắt nhỏ này nằm ĐÂU ĐÓ trong văn bản gốc. Hãy nhìn vào nội dung ảnh cắt và tìm đoạn văn tương ứng trong tài liệu gốc.
      3. Chèn thẻ [[IMAGE_X]] (với X là số thứ tự ảnh 1, 2, 3...) vào CHÍNH XÁC vị trí mà ảnh đó xuất hiện so với văn bản xung quanh. 
      4. KHÔNG liệt kê tất cả ảnh ở cuối tài liệu. Phải đặt chúng xen kẽ vào đúng ngữ cảnh.

      ĐỊNH DẠNG TOÁN HỌC:
      ${mathInstructions}

      ${solutionPrompt}
      ${similarPrompt}

      BẢNG BIỂU: Tái tạo bằng <table> sạch.
      HÌNH ẢNH: Chèn thẻ [[IMAGE_X]] vào vị trí logic.
      OUTPUT: Trả về HTML bên trong <body>. Không dùng markdown code blocks.
    `;

    parts.push({ text: prompt });

    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts: parts }
    });

    let text = response.text || "";
    let cleanHtml = text.replace(/```html/g, '').replace(/```/g, '').trim();

    // LaTeX Post-processing
    if (mathFormat === 'latex') {
      // Xử lý các trường hợp Alphanumeric ngắn (7A, 7B, 10C, A1, ...)
      // Tìm các $...$ có chứa cả chữ và số hoặc chỉ chữ/số ngắn và bọc trong {}
      cleanHtml = cleanHtml.replace(/\$([A-Za-z0-9,;.\s]+)\$/g, (m, p1) => {
          const t = p1.trim();
          // Nếu đã có ngoặc nhọn hoặc là chuỗi dài (công thức phức tạp) thì bỏ qua
          if (!t || t.startsWith('{') || t.length > 12) return m;

          // Ưu tiên bọc các định danh kiểu 7A, 7B, A, B, 123
          return `$\{${t}\}$`;
      });

      // Đảm bảo các ký tự đơn lẻ hoặc số đơn lẻ cũng được bọc đúng
      cleanHtml = cleanHtml.replace(/\$([0-9,;.\s]+)\$/g, (m, p1) => {
          const t = p1.trim();
          if (!t || t.startsWith('{') || !/[0-9]/.test(t)) return m;
          return `$\{${t}\}$`;
      });
      cleanHtml = cleanHtml.replace(/\$([A-Za-z.,\s]+)\$/g, (m, p1) => {
          const t = p1.trim();
          if (!t || t.startsWith('{') || !/[A-Za-z]/.test(t) || /^[.,\s]+$/.test(t)) return m;
          return `$\{${t}\}$`;
      });
    }

    // Thay thế placeholder bằng tag img thật, bọc trong div căn giữa
    if (croppedImages.length > 0) {
        croppedImages.forEach((img, index) => {
            const placeholder = `[[IMAGE_${index + 1}]]`;
            const imgTag = `<div style="text-align:center; margin: 15px 0;"><img src="${img.base64}" style="max-width:100%; border: 1px solid #eee;" alt="Inserted Image ${index + 1}" /></div>`;
            // Sử dụng regex để thay thế tất cả instances của placeholder này
            const regex = new RegExp(`\\[\\[IMAGE_${index + 1}\\]\\]`, 'g');
            cleanHtml = cleanHtml.replace(regex, imgTag);
        });
    }

    return cleanHtml;
  } catch (error) {
    console.error("Gemini Error:", error);
    throw new Error("Lỗi khi kết nối với AI. Vui lòng thử lại.");
  }
};

