                      <label className="text-xs font-bold text-gray-600">Mức độ tương đồng:</label>
                      <div className="flex bg-gray-100 p-1 rounded-md text-[10px]">
                        <button onClick={() => setSimilarityLevel('numbers')} className={`flex-1 py-1 rounded ${similarityLevel === 'numbers' ? 'bg-white shadow-sm text-indigo-600 font-bold' : 'text-gray-400'}`}>Chỉ đổi số</button>
                        <button onClick={() => setSimilarityLevel('type')} className={`flex-1 py-1 rounded ${similarityLevel === 'type' ? 'bg-white shadow-sm text-indigo-600 font-bold' : 'text-gray-400'}`}>Dạng bài</button>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>

            <FileUpload onFileSelect={handleFileSelect} disabled={false} />
          </div>
        )}

        {status === AppStatus.CROP_SELECT && currentFiles.length > 0 && (
            <ImageCropper 
              files={currentFiles} 
              externalCrops={croppedImages}
              onComplete={handleCropComplete} 
              onCancel={handleCropCancel} 
            />
        )}

        {(status === AppStatus.PROCESSING) && (
          <ProcessingView files={fileProgress} isComplete={false} onCancel={handleCancelProcess} />
        )}

        {status === AppStatus.COMPLETE && results.length > 0 && (
          <ResultPreview results={results} onReset={() => setStatus(AppStatus.IDLE)} />
        )}

        {status === AppStatus.ERROR && (
          <div className="bg-white rounded-xl shadow-lg border border-red-100 p-8 text-center max-w-md mx-auto animate-fade-in">
             <AlertTriangle className="w-12 h-12 text-red-500 mx-auto mb-4" />
             <h3 className="text-lg font-bold text-gray-900">Lỗi xử lý</h3>
             <p className="text-gray-600 mt-2 mb-6">{errorMessage}</p>
             <button onClick={() => setStatus(AppStatus.IDLE)} className="px-8 py-2 bg-gray-900 text-white rounded-lg hover:bg-black transition-colors">Thử lại</button>
          </div>
        )}
      </main>

      <footer className="py-6 border-t border-gray-200 bg-white mt-auto text-center text-xs text-gray-400">
        © {new Date().getFullYear()} AI Document Hub. Multi-file Processing Enabled.
      </footer>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { ChevronLeft, ChevronRight, Crop, Check, X, Image as ImageIcon, ZoomIn, ZoomOut, MousePointer2, Trash2, Files } from 'lucide-react';
import { CroppedImage, FileData } from '../types';

interface ImageCropperProps {
  files: FileData[];
  externalCrops?: CroppedImage[];
  onComplete: (images: CroppedImage[]) => void;
  onCancel: () => void;
}

const RESOLUTION_FACTOR = 4;

export const ImageCropper: React.FC<ImageCropperProps> = ({ files, externalCrops = [], onComplete, onCancel }) => {
  // Lọc các tệp có thể cắt được
  const croppableFiles = useMemo(() => 
    files.filter(f => f.type === 'application/pdf' || f.type.startsWith('image/')),
    [files]
  );

  const [activeFileIndex, setActiveFileIndex] = useState(0);
  const currentFile = croppableFiles[activeFileIndex];

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [pdfDoc, setPdfDoc] = useState<any>(null);
  const [imageObj, setImageObj] = useState<HTMLImageElement | null>(null);
  const [pageNum, setPageNum] = useState(1);
  const [scale, setScale] = useState(1.0);
  const [isDrawing, setIsDrawing] = useState(false);
  const [selection, setSelection] = useState<{ x: number; y: number; w: number; h: number } | null>(null);
  const [startPos, setStartPos] = useState<{ x: number; y: number }>({ x: 0, y: 0 });
  const [croppedImages, setCroppedImages] = useState<CroppedImage[]>([]);
  const [loading, setLoading] = useState(true);

  const isPdf = currentFile?.type === 'application/pdf';

  // Đồng bộ ảnh đã cắt từ paste hoặc ban đầu
  useEffect(() => {
    if (externalCrops.length > 0) {
      setCroppedImages(prev => {
        const existingIds = new Set(prev.map(c => c.id));
        const newOnes = externalCrops.filter(c => !existingIds.has(c.id));
        return [...prev, ...newOnes];
      });
    }
  }, [externalCrops]);

  // Reset tài liệu khi đổi tệp
  useEffect(() => {
    const loadContent = async () => {
      if (!currentFile) return;
      setLoading(true);
      setPdfDoc(null);
      setImageObj(null);
      setPageNum(1);

      try {
        if (isPdf) {
          const loadingTask = (window as any).pdfjsLib.getDocument(currentFile.base64);
          const pdf = await loadingTask.promise;
          setPdfDoc(pdf);
        } else if (currentFile.type.startsWith('image/')) {
          const img = new Image();
          img.onload = () => {
            setImageObj(img);
            setLoading(false);
          };
          img.src = currentFile.base64;
        }
        if (isPdf) setLoading(false);
      } catch (error) {
        console.error("Error loading file in cropper:", error);
        setLoading(false);
      }
    };
    loadContent();
  }, [currentFile, isPdf]);

  // Vẽ nội dung lên canvas
  useEffect(() => {
    if ((!pdfDoc && !imageObj) || !canvasRef.current) return;
    const render = async () => {
      const canvas = canvasRef.current!;
      const context = canvas.getContext('2d', { willReadFrequently: true })!;
      if (isPdf && pdfDoc) {
        const page = await pdfDoc.getPage(pageNum);
        const highResViewport = page.getViewport({ scale: scale * RESOLUTION_FACTOR });
        canvas.height = highResViewport.height;
        canvas.width = highResViewport.width;
        canvas.style.width = `${highResViewport.width / RESOLUTION_FACTOR}px`;
        canvas.style.height = `${highResViewport.height / RESOLUTION_FACTOR}px`;
        await page.render({ canvasContext: context, viewport: highResViewport }).promise;
      } else if (imageObj) {
        const renderWidth = imageObj.width * scale * RESOLUTION_FACTOR;
        const renderHeight = imageObj.height * scale * RESOLUTION_FACTOR;
        canvas.width = renderWidth;
        canvas.height = renderHeight;
        canvas.style.width = `${renderWidth / RESOLUTION_FACTOR}px`;
        canvas.style.height = `${renderHeight / RESOLUTION_FACTOR}px`;
        context.drawImage(imageObj, 0, 0, renderWidth, renderHeight);
      }
    };
    render();
  }, [pdfDoc, imageObj, pageNum, scale, isPdf]);

  const getCoordinates = (e: React.MouseEvent) => {
    if (!canvasRef.current) return { x: 0, y: 0 };
    const rect = canvasRef.current.getBoundingClientRect();
    return { x: e.clientX - rect.left, y: e.clientY - rect.top };
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDrawing(true);
    const pos = getCoordinates(e);
    setStartPos(pos);
    setSelection({ x: pos.x, y: pos.y, w: 0, h: 0 });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDrawing) return;
    const pos = getCoordinates(e);
    setSelection({
      x: Math.min(pos.x, startPos.x),
      y: Math.min(pos.y, startPos.y),
      w: Math.abs(pos.x - startPos.x),
      h: Math.abs(pos.y - startPos.y)
    });
  };

  const saveCrop = () => {
    if (!selection || !canvasRef.current || selection.w < 5) return;
    const sourceCanvas = canvasRef.current;
    const sourceX = selection.x * RESOLUTION_FACTOR;
    const sourceY = selection.y * RESOLUTION_FACTOR;
    const sourceW = selection.w * RESOLUTION_FACTOR;
    const sourceH = selection.h * RESOLUTION_FACTOR;
    const destCanvas = document.createElement('canvas');
    destCanvas.width = sourceW;
    destCanvas.height = sourceH;
    const ctx = destCanvas.getContext('2d')!;
    ctx.drawImage(sourceCanvas, sourceX, sourceY, sourceW, sourceH, 0, 0, sourceW, sourceH);
    setCroppedImages([...croppedImages, { id: Date.now().toString(), base64: destCanvas.toDataURL('image/png'), page: pageNum }]);
    setSelection(null);
  };

  if (loading && !pdfDoc && !imageObj) return <div className="fixed inset-0 bg-white flex items-center justify-center z-[100]"><p className="font-bold text-blue-600 animate-pulse">Đang tải tài liệu...</p></div>;

  return (
    <div className="w-full h-full flex flex-col bg-gray-50 fixed inset-0 z-50 md:relative md:h-[80vh] border border-gray-200 shadow-2xl rounded-xl overflow-hidden">
      {/* Top Header */}
      <div className="bg-white border-b border-gray-200 p-3 flex items-center justify-between z-10">
        <div className="flex items-center gap-3">
          {isPdf && (
            <div className="flex items-center gap-1 bg-gray-100 rounded-lg p-1">
              <button onClick={() => setPageNum(p => Math.max(1, p - 1))} disabled={pageNum <= 1} className="p-1 disabled:opacity-30"><ChevronLeft className="w-5 h-5"/></button>
              <span className="text-xs font-bold w-12 text-center">{pageNum}/{pdfDoc?.numPages}</span>
              <button onClick={() => setPageNum(p => Math.min(pdfDoc?.numPages, p + 1))} disabled={pageNum >= pdfDoc?.numPages} className="p-1 disabled:opacity-30"><ChevronRight className="w-5 h-5"/></button>
            </div>
          )}
          <div className="flex items-center gap-1 bg-gray-100 rounded-lg p-1">
            <button onClick={() => setScale(s => Math.max(0.3, s - 0.2))} className="p-1"><ZoomOut className="w-4 h-4"/></button>
            <span className="text-xs font-bold w-10 text-center">{Math.round(scale * 100)}%</span>
            <button onClick={() => setScale(s => Math.min(3, s + 0.2))} className="p-1"><ZoomIn className="w-4 h-4"/></button>
          </div>
          <div className="hidden lg:flex items-center gap-2 px-3 py-1 bg-blue-50 text-blue-600 rounded-full border border-blue-100 text-[10px] font-bold uppercase tracking-wide">
            <MousePointer2 className="w-3 h-3" />
            Kéo chuột để cắt hoặc Ctrl+V để dán ảnh
          </div>
        </div>
        <div className="flex items-center gap-2">
            <button 
              onClick={() => {
                if(window.confirm("Bạn có chắc chắn muốn xóa toàn bộ ảnh đã cắt?")) {
                  setCroppedImages([]);
                }
              }} 
              className="px-3 py-1.5 text-xs font-bold text-gray-400 hover:text-red-600 flex items-center gap-1.5 transition-colors"
            >
              <Trash2 className="w-3.5 h-3.5" />
              XÓA HẾT
            </button>
            <button onClick={() => onComplete(croppedImages)} className="px-6 py-2 bg-blue-600 text-white rounded-lg text-xs font-bold flex items-center gap-2 hover:bg-blue-700 transition-all shadow-md">
                <Check className="w-4 h-4" /> BẮT ĐẦU CHUYỂN ĐỔI ({croppedImages.length} ẢNH)
            </button>
        </div>
      </div>

      <div className="flex flex-1 overflow-hidden">
        {/* Left Sidebar: Source Files List */}
        {croppableFiles.length > 1 && (
          <div className="w-60 bg-white border-r border-gray-200 flex flex-col shrink-0">
            <div className="p-4 border-b border-gray-100 bg-gray-50 flex items-center gap-2">
              <Files className="w-4 h-4 text-blue-600" />
              <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest">NGUỒN CẮT ẢNH</h3>
            </div>
            <div className="flex-1 overflow-y-auto p-2 space-y-1 custom-scrollbar">
              {croppableFiles.map((f, idx) => (
                <button
                  key={idx}
                  onClick={() => setActiveFileIndex(idx)}
                  className={`w-full text-left p-3 rounded-lg text-xs transition-all flex items-center gap-3 ${activeFileIndex === idx ? 'bg-blue-50 text-blue-700 font-bold border border-blue-100' : 'text-gray-500 hover:bg-gray-100'}`}
                >
                  <ImageIcon className="w-4 h-4 shrink-0" />
                  <span className="truncate">{f.name}</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Main Workspace */}
        <div className="flex-1 overflow-auto p-8 bg-gray-200 flex justify-center relative">
          <div className="relative shadow-2xl h-fit">
            <canvas 
              ref={canvasRef} 
              onMouseDown={handleMouseDown} 
              onMouseMove={handleMouseMove} 
              onMouseUp={() => setIsDrawing(false)} 
              className="cursor-crosshair bg-white transition-opacity duration-300" 
              style={{ opacity: loading ? 0.5 : 1 }}
            />
            {selection && <div className="absolute border-2 border-blue-500 bg-blue-500/10 pointer-events-none" style={{ left: selection.x, top: selection.y, width: selection.w, height: selection.h }} />}
            {selection && selection.w > 10 && !isDrawing && (
              <button 
                onClick={saveCrop} 
                className="absolute z-20 bg-blue-600 text-white p-2 rounded-full shadow-lg hover:scale-110 active:scale-95 transition-all" 
                style={{ left: selection.x + selection.w - 15, top: selection.y + selection.h - 15 }}
              >
                <Crop className="w-4 h-4" />
              </button>
            )}
          </div>
        </div>

        {/* Right Sidebar: Selected Images List */}
        <div className="w-64 bg-white border-l border-gray-200 flex flex-col shrink-0">
           <div className="p-4 border-b border-gray-100 bg-gray-50 flex items-center justify-between">
             <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
               <ImageIcon className="w-3 h-3" /> GIỎ ẢNH ({croppedImages.length})
             </h3>
           </div>
           <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
              {croppedImages.length === 0 ? (
                  <div className="text-center text-gray-200 py-20">
                    <Crop className="w-12 h-12 mx-auto mb-3 opacity-20" />
                    <p className="text-[10px] uppercase font-bold tracking-wider">Chưa có ảnh</p>
                  </div>
              ) : (
                  [...croppedImages].reverse().map((img, idx) => (
                      <div key={img.id} className="relative group bg-white rounded border border-gray-200 p-1 shadow-sm overflow-hidden animate-scale-up">
                          <img src={img.base64} className="w-full h-auto max-h-32 object-contain bg-gray-50 rounded" />
                          <div className="mt-1 flex justify-between items-center px-1 py-1 bg-gray-50 border-t border-gray-100">
                              <span className="text-[9px] font-bold text-gray-400"># {croppedImages.length - idx}</span>
                              <button 
                                onClick={() => setCroppedImages(croppedImages.filter(c => c.id !== img.id))} 
                                className="flex items-center gap-1 text-[9px] font-bold text-red-400 hover:text-red-600 transition-colors"
                              >
                                <X className="w-2.5 h-2.5" />
                                XÓA
                              </button>
                          </div>
                          {img.page === 0 && <span className="absolute top-1 right-1 bg-amber-500 text-white text-[7px] px-1 rounded shadow-sm font-bold">PASTED</span>}
                      </div>
                  ))
              )}
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Download, RefreshCw, FileText, Check, Copy, Settings2, ChevronDown, ChevronUp, Type, AlignLeft, List, Archive, Loader2 } from 'lucide-react';
import { ConversionResult } from '../types';

// Declare JSZip globally
declare const JSZip: any;

interface ResultPreviewProps {
  results: ConversionResult[];
  onReset: () => void;
}

export const ResultPreview: React.FC<ResultPreviewProps> = ({ results, onReset }) => {
  const [selectedIndex, setSelectedIndex] = useState(0);
  const [copied, setCopied] = useState(false);
  const [isOptionsOpen, setIsOptionsOpen] = useState(false);
  const [isZipping, setIsZipping] = useState(false);

  // Formatting state
  const [lineHeight, setLineHeight] = useState('1.5');
  const [bodyFontSize, setBodyFontSize] = useState('12');
  const [headingFontSize, setHeadingFontSize] = useState('16');

  const currentResult = results[selectedIndex];

  // Helper function to generate Word HTML content
  const generateWordContent = (content: string, fileName: string) => {
    return `
      <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
      <head>
        <meta http-equiv="Content-Type" content="text/html; charset=utf-8">
        <title>${fileName}</title>
        <style>
          body { 
            font-family: 'Times New Roman', serif; 
            font-size: ${bodyFontSize}pt; 
            line-height: ${lineHeight};
          }
          table { 
            border-collapse: collapse; 
            width: 100%; 
            margin-bottom: 1em;
            border: 1px solid windowtext;
            mso-border-alt: solid windowtext .5pt;
          }
          td, th { 
            border: 1px solid windowtext; 
            padding: 5px 8px; 
            vertical-align: top;
            mso-border-alt: solid windowtext .5pt;
          }
          th { background-color: #f2f2f2; font-weight: bold; }
          h1 { font-size: ${parseInt(headingFontSize) + 4}pt; font-weight: bold; margin: 12pt 0 6pt 0; }
          h2 { font-size: ${headingFontSize}pt; font-weight: bold; margin: 10pt 0 5pt 0; }
          h3 { font-size: ${parseInt(headingFontSize) - 2}pt; font-weight: bold; margin: 8pt 0 4pt 0; }
          p { margin: 0 0 1em 0; }
          div.img-container { text-align: center; margin: 10px 0; }
        </style>
      </head>
      <body>
        ${content}
      </body>
      </html>
    `;
  };

  const handleCopy = () => {
    if (!currentResult) return;
    const tempDiv = document.createElement('div');
    tempDiv.innerHTML = currentResult.content;
    const text = tempDiv.innerText;

    const listener = (e: ClipboardEvent) => {
      e.preventDefault();
      if (e.clipboardData) {
        e.clipboardData.setData('text/html', currentResult.content);
        e.clipboardData.setData('text/plain', text);
      }
    };
    document.addEventListener('copy', listener);
    document.execCommand('copy');
    document.removeEventListener('copy', listener);

    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDownload = (index: number) => {
    const res = results[index];
    if (!res) return;

    const fileContent = generateWordContent(res.content, res.fileName);

    const blob = new Blob(['\uFEFF', fileContent], {
      type: 'application/msword;charset=utf-8'
    });

    const url = URL.createObjectURL(blob);
    const downloadLink = document.createElement("a");
    downloadLink.href = url;
    const safeName = res.fileName.replace(/\.[^/.]+$/, "");
    downloadLink.download = `${safeName}.doc`;
    document.body.appendChild(downloadLink);
    downloadLink.click();
    document.body.removeChild(downloadLink);
    setTimeout(() => URL.revokeObjectURL(url), 100);
  };

  const handleDownloadAll = async () => {
    // If JSZip is not available, fallback to individual downloads
    if (typeof JSZip === 'undefined') {
        console.warn("JSZip not loaded, falling back to multiple file downloads.");
        results.forEach((_, i) => handleDownload(i));
        return;
    }

    setIsZipping(true);
    try {
        const zip = new JSZip();

        results.forEach((res) => {
            const content = generateWordContent(res.content, res.fileName);
            const safeName = res.fileName.replace(/\.[^/.]+$/, "");
            zip.file(`${safeName}.doc`, content);
        });

        const content = await zip.generateAsync({ type: "blob" });
        const url = URL.createObjectURL(content);
        const a = document.createElement("a");
        a.href = url;
        a.download = `converted_documents_${new Date().toISOString().slice(0,10)}.zip`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        setTimeout(() => URL.revokeObjectURL(url), 100);
    } catch (error) {
        console.error("Zip error:", error);
        alert("Có lỗi khi nén file. Hệ thống sẽ tải xuống từng file.");
        results.forEach((_, i) => handleDownload(i));
    } finally {
        setIsZipping(false);
    }
  };

  return (
    <div className="w-full max-w-6xl mx-auto space-y-4 animate-fade-in-up flex flex-col lg:flex-row gap-6">

      {/* Sidebar for multiple files */}
      {results.length > 1 && (
        <div className="w-full lg:w-64 flex-shrink-0 space-y-4">
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
            <div className="p-3 bg-gray-50 border-b border-gray-200 flex items-center gap-2">
              <List className="w-4 h-4 text-blue-600" />
              <span className="text-xs font-bold text-gray-600 uppercase">Danh sách tệp ({results.length})</span>
            </div>
            <div className="max-h-[60vh] overflow-y-auto p-2 space-y-1 custom-scrollbar">
              {results.map((res, idx) => (
                <button
                  key={idx}
                  onClick={() => setSelectedIndex(idx)}
                  className={`w-full text-left p-3 rounded-lg text-xs transition-all flex items-center gap-3 ${selectedIndex === idx ? 'bg-blue-50 text-blue-700 font-bold border border-blue-100 shadow-sm' : 'text-gray-600 hover:bg-gray-100'}`}
                >
                  <FileText className={`w-4 h-4 flex-shrink-0 ${selectedIndex === idx ? 'text-blue-600' : 'text-gray-400'}`} />
                  <span className="truncate">{res.fileName}</span>
                </button>
              ))}
            </div>
          </div>

          <button 
            onClick={handleDownloadAll}
            disabled={isZipping}
            className={`w-full py-3 bg-gray-800 hover:bg-black text-white rounded-xl text-xs font-bold transition-all shadow-md flex items-center justify-center gap-2 ${isZipping ? 'opacity-70 cursor-wait' : ''}`}
          >
            {isZipping ? <Loader2 className="w-4 h-4 animate-spin" /> : <Archive className="w-4 h-4" />}
            {isZipping ? 'ĐANG NÉN...' : `TẢI ZIP TẤT CẢ (${results.length})`}
          </button>
        </div>
      )}

      <div className="flex-grow space-y-4">
        {/* Formatting Options Accordion */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
          <button 
            onClick={() => setIsOptionsOpen(!isOptionsOpen)}
            className="w-full flex items-center justify-between p-4 hover:bg-gray-50 transition-colors"
          >
            <div className="flex items-center gap-2 text-gray-700 font-semibold">
              <Settings2 className="w-4 h-4 text-blue-500" />
              <span className="text-sm">Tùy chọn định dạng (Formatting Options)</span>
            </div>
            {isOptionsOpen ? <ChevronUp className="w-4 h-4 text-gray-400" /> : <ChevronDown className="w-4 h-4 text-gray-400" />}
          </button>

          {isOptionsOpen && (
            <div className="p-4 border-t border-gray-100 grid grid-cols-1 md:grid-cols-3 gap-6 bg-gray-50/50">
              <div className="space-y-2">
                <label className="flex items-center gap-2 text-xs font-bold text-gray-500 uppercase">
                  <AlignLeft className="w-3.5 h-3.5" /> Giãn dòng
                </label>
                <select 
                  value={lineHeight}
                  onChange={(e) => setLineHeight(e.target.value)}
                  className="w-full text-sm p-2 rounded-lg border border-gray-200 bg-white focus:ring-2 focus:ring-blue-500 outline-none"
                >
                  <option value="1.0">Đơn (Single)</option>
                  <option value="1.15">1.15 lines</option>
                  <option value="1.5">1.5 lines</option>
                  <option value="2.0">Đôi (Double)</option>
                </select>
              </div>

              <div className="space-y-2">
                <label className="flex items-center gap-2 text-xs font-bold text-gray-500 uppercase">
                  <Type className="w-3.5 h-3.5" /> Cỡ chữ nội dung
                </label>
                <div className="flex items-center gap-3">
                  <input 
                    type="range" min="10" max="18" step="1"
                    value={bodyFontSize}
                    onChange={(e) => setBodyFontSize(e.target.value)}
                    className="flex-grow h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600"
                  />
                  <span className="text-xs font-bold text-blue-600 w-8">{bodyFontSize}pt</span>
                </div>
              </div>

              <div className="space-y-2">
                <label className="flex items-center gap-2 text-xs font-bold text-gray-500 uppercase">
                  <Type className="w-3.5 h-3.5" /> Cỡ chữ tiêu đề
                </label>
                <div className="flex items-center gap-3">
                  <input 
                    type="range" min="14" max="24" step="1"
                    value={headingFontSize}
                    onChange={(e) => setHeadingFontSize(e.target.value)}
                    className="flex-grow h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600"
                  />
                  <span className="text-xs font-bold text-blue-600 w-8">{headingFontSize}pt</span>
                </div>
              </div>
            </div>
          )}
        </div>

        <div className="bg-white rounded-xl shadow-lg border border-gray-200 overflow-hidden flex flex-col h-[65vh] min-h-[500px]">
          <div className="p-4 border-b border-gray-100 bg-gray-50 flex items-center justify-between flex-shrink-0">
            <div className="flex items-center gap-2 text-gray-700 overflow-hidden">
              <FileText className="w-5 h-5 text-blue-500 shrink-0" />
              <span className="font-semibold truncate text-sm">Xem trước: {currentResult?.fileName}</span>
            </div>
            <button 
              onClick={handleCopy}
              className="flex items-center gap-1.5 text-xs font-medium text-gray-600 bg-white px-3 py-1.5 rounded-lg border border-gray-200 hover:bg-gray-50 transition-colors shrink-0"
            >
               {copied ? <Check className="w-3.5 h-3.5 text-green-600" /> : <Copy className="w-3.5 h-3.5" />}
               {copied ? 'Đã sao chép' : 'Sao chép'}
            </button>
          </div>

          <div className="flex-grow bg-gray-100 overflow-y-auto p-4 sm:p-8 custom-scrollbar">
              <div className="bg-white shadow-sm min-h-full p-10 max-w-[21cm] mx-auto text-gray-900 leading-relaxed font-serif overflow-hidden">
                  <div 
                    style={{ lineHeight: lineHeight, fontSize: `${bodyFontSize}pt` }}
                    className="prose prose-slate max-w-none prose-p:font-serif prose-p:mb-4 prose-headings:font-bold prose-headings:font-serif prose-headings:text-gray-900"
                    dangerouslySetInnerHTML={{ __html: currentResult?.content || '' }} 
                  />
              </div>
          </div>

          <div className="p-6 bg-white border-t border-gray-100 flex flex-col sm:flex-row gap-4 items-center justify-between flex-shrink-0">
            <button
              onClick={onReset}
              className="w-full sm:w-auto flex items-center justify-center gap-2 px-6 py-3 text-gray-600 bg-gray-100 hover:bg-gray-200 rounded-xl font-medium transition-colors"
            >
              <RefreshCw className="w-4 h-4" />
              Chuyển đổi mới
            </button>

            <button
              onClick={() => handleDownload(selectedIndex)}
              className="w-full sm:w-auto flex items-center justify-center gap-2 px-8 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-semibold shadow-lg shadow-blue-200 transition-all hover:scale-[1.02] active:scale-[0.98]"
            >
              <Download className="w-5 h-5" />
              Tải xuống Word (.doc)
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export enum AppStatus {
  IDLE = 'IDLE',
  READY = 'READY', // New status: Files selected, options adjustable, waiting for start
  UPLOADING = 'UPLOADING',
  CROP_SELECT = 'CROP_SELECT',
  PROCESSING = 'PROCESSING',
  COMPLETE = 'COMPLETE',
  ERROR = 'ERROR',
}

export interface ConversionResult {
  content: string;
  fileName: string;
}

export interface FileData {
  name: string;
  size: number;
  type: string;
  base64: string;
}

export interface CroppedImage {
  id: string;
  base64: string;
  page: number;
}

export type SimilarityLevel = 'numbers' | 'type';
export type MathFormat = 'latex' | 'equation';

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Header } from './components/Header';
import { FileUpload } from './components/FileUpload';
import { ProcessingView } from './components/ProcessingView';
import { ResultPreview } from './components/ResultPreview';
import { ImageCropper } from './components/ImageCropper';
import { AppStatus, ConversionResult, FileData, CroppedImage, SimilarityLevel, MathFormat } from './types';
import { convertDocument } from './services/geminiService';
import { AlertTriangle, BrainCircuit, Layers, FunctionSquare, Binary, FileStack, X, Play, Trash2 } from 'lucide-react';

interface FileProcessingState {
  name: string;
  status: 'waiting' | 'processing' | 'complete' | 'error';
}

const App: React.FC = () => {
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [currentFiles, setCurrentFiles] = useState<FileData[]>([]);
  const [results, setResults] = useState<ConversionResult[]>([]);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [croppedImages, setCroppedImages] = useState<CroppedImage[]>([]);
  const [fileProgress, setFileProgress] = useState<FileProcessingState[]>([]);

  const isCancelledRef = useRef<boolean>(false);

  const [includeSolutions, setIncludeSolutions] = useState<boolean>(false);
  const [generateSimilar, setGenerateSimilar] = useState<boolean>(false);
  const [similarCount, setSimilarCount] = useState<number>(1);
  const [similarityLevel, setSimilarityLevel] = useState<SimilarityLevel>('numbers');
  const [mathFormat, setMathFormat] = useState<MathFormat>('latex');

  const processAllFiles = async (files: FileData[], images: CroppedImage[]) => {
    isCancelledRef.current = false;
    setResults([]);

    setFileProgress(files.map(f => ({ name: f.name, status: 'waiting' })));

    const conversionPromises = files.map(async (file, index) => {
      setFileProgress(prev => {
        const next = [...prev];
        if (next[index]) next[index].status = 'processing';
        return next;
      });

      try {
        const htmlContent = await convertDocument(
          file, 
          // Gửi toàn bộ ảnh đã cắt cho từng file, AI sẽ tự tìm ảnh phù hợp với nội dung
          images, 
          includeSolutions, 
          generateSimilar, 
          similarCount, 
          similarityLevel,
          mathFormat
        );

        if (isCancelledRef.current) return null;

        setFileProgress(prev => {
          const next = [...prev];
          if (next[index]) next[index].status = 'complete';
          return next;
        });

        return { content: htmlContent, fileName: file.name };
      } catch (error) {
        console.error(`Error processing ${file.name}:`, error);
        setFileProgress(prev => {
          const next = [...prev];
          if (next[index]) next[index].status = 'error';
          return next;
        });
        return null;
      }
    });

    const finalResults = await Promise.all(conversionPromises);

    if (isCancelledRef.current) return;

    const successfulResults = finalResults.filter((r): r is ConversionResult => r !== null);

    if (successfulResults.length === 0) {
      setStatus(AppStatus.ERROR);
      setErrorMessage("Không thể chuyển đổi bất kỳ tệp nào. Vui lòng kiểm tra lại tệp đầu vào.");
    } else {
      setResults(successfulResults);
      setStatus(AppStatus.COMPLETE);
    }
  };

  const handleFileSelect = useCallback((files: FileList) => {
    setErrorMessage(null);
    setCroppedImages([]);
    const fileArray = Array.from(files);

    const loadFiles = async () => {
      const fileDataPromises = fileArray.map(file => {
        return new Promise<FileData>((resolve) => {
          const reader = new FileReader();
          reader.onload = (e) => {
            resolve({
              name: file.name,
              size: file.size,
              type: file.type,
              base64: e.target?.result as string
            });
          };
          reader.readAsDataURL(file);
        });
      });

      const loadedFiles = await Promise.all(fileDataPromises);
      setCurrentFiles(loadedFiles);
      setStatus(AppStatus.READY); // Chuyển sang trạng thái READY thay vì xử lý ngay
    };

    loadFiles();
  }, []); // Removed dependencies since we don't process immediately anymore

  useEffect(() => {
    const handlePaste = async (event: ClipboardEvent) => {
      const items = event.clipboardData?.items;
      if (!items) return;

      const imageBlobs: File[] = [];
      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const blob = items[i].getAsFile();
          if (blob) imageBlobs.push(blob);
        }
      }

      if (imageBlobs.length === 0) return;

      const blobToCrop = (blob: File, index: number): Promise<CroppedImage> => {
        return new Promise((resolve) => {
          const reader = new FileReader();
          reader.onload = (e) => {
            resolve({
              id: `pasted-${Date.now()}-${index}`,
              base64: e.target?.result as string,
              page: 0
            });
          };
          reader.readAsDataURL(blob);
        });
      };

      if (status === AppStatus.IDLE) {
        const firstBlob = imageBlobs[0];
        const reader = new FileReader();
        reader.onload = async (e) => {
          const base64 = e.target?.result as string;
          const fileData: FileData = {
            name: `pasted-images-${Date.now()}.png`,
            size: firstBlob.size,
            type: firstBlob.type,
            base64: base64
          };
          setCurrentFiles([fileData]);

          const newCrops = await Promise.all(imageBlobs.map((blob, idx) => blobToCrop(blob, idx)));
          setCroppedImages(newCrops);
          // Với paste, chúng ta vẫn cho phép vào thẳng crop nếu muốn, hoặc vào READY
          // Để nhất quán, vào CROP_SELECT vì paste thường cần cắt ngay
          setStatus(AppStatus.CROP_SELECT);
        };
        reader.readAsDataURL(firstBlob);
      } else if (status === AppStatus.CROP_SELECT) {
        const newCrops = await Promise.all(imageBlobs.map((blob, idx) => blobToCrop(blob, idx)));
        setCroppedImages(prev => [...prev, ...newCrops]);
      } else if (status === AppStatus.READY) {
          // Nếu đang ở màn hình Ready mà paste, thêm file vào danh sách
          const newFilesPromises = imageBlobs.map(blob => new Promise<FileData>((resolve) => {
             const reader = new FileReader();
             reader.onload = (e) => resolve({
                 name: `pasted-${Date.now()}.png`,
                 size: blob.size,
                 type: blob.type,
                 base64: e.target?.result as string
             });
             reader.readAsDataURL(blob);
          }));
          const newFiles = await Promise.all(newFilesPromises);
          setCurrentFiles(prev => [...prev, ...newFiles]);
      }
    };

    window.addEventListener('paste', handlePaste);
    return () => window.removeEventListener('paste', handlePaste);
  }, [status]);

  const handleStartProcessing = () => {
      // Kiểm tra xem có cần cắt ảnh không (PDF hoặc Image)
      const hasCroppable = currentFiles.some(f => f.type === 'application/pdf' || f.type.startsWith('image/'));

      if (hasCroppable) {
        setStatus(AppStatus.CROP_SELECT);
      } else {
        setStatus(AppStatus.PROCESSING);
        processAllFiles(currentFiles, []);
      }
  };

  const handleReset = () => {
      setStatus(AppStatus.IDLE);
      setCurrentFiles([]);
      setCroppedImages([]);
      setFileProgress([]);
  };

  const handleRemoveFile = (index: number) => {
      const newFiles = [...currentFiles];
      newFiles.splice(index, 1);
      if (newFiles.length === 0) {
          handleReset();
      } else {
          setCurrentFiles(newFiles);
      }
  };

  const handleCropComplete = (images: CroppedImage[]) => {
    setCroppedImages(images);
    if (currentFiles.length > 0) {
        setStatus(AppStatus.PROCESSING);
        processAllFiles(currentFiles, images);
    }
  };

  const handleCropCancel = () => {
      if (currentFiles.length > 0) {
          setStatus(AppStatus.PROCESSING);
          processAllFiles(currentFiles, []);
      }
  };

  const handleCancelProcess = () => {
    isCancelledRef.current = true;
    setStatus(AppStatus.READY); // Quay lại READY thay vì IDLE để người dùng không mất file
    setFileProgress([]);
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Header />

      <main className="flex-grow container mx-auto px-4 py-8 flex flex-col items-center justify-start gap-6 relative">

        {(status === AppStatus.IDLE || status === AppStatus.READY) && (
          <div className="text-center max-w-2xl mx-auto mb-2">
            <h2 className="text-4xl font-extrabold text-gray-900 tracking-tight mb-2">
              Chuyển đổi <span className="text-blue-600">Đa tệp</span>
            </h2>
            <p className="text-gray-600">Trích xuất văn bản & hỗ trợ Equation/LaTeX cho Microsoft Word.</p>
          </div>
        )}

        {/* Khu vực hiển thị khi IDLE hoặc READY (Hiển thị Options ở cả 2 trạng thái) */}
        {(status === AppStatus.IDLE || status === AppStatus.READY) && (
          <div className="w-full max-w-2xl mx-auto space-y-4">

            {/* Options Panel */}
            <div className="bg-white p-5 rounded-xl border border-gray-200 shadow-sm space-y-5 animate-fade-in-up">
               {/* 1. Tùy chọn giải toán & bài tập tương tự */}
               <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  <div className={`p-4 rounded-xl border-2 transition-all flex items-center justify-between cursor-pointer ${includeSolutions ? 'bg-blue-50 border-blue-200 shadow-sm' : 'bg-white border-gray-100 hover:border-gray-200'}`} onClick={() => setIncludeSolutions(!includeSolutions)}>
                    <div className="flex items-center gap-3">
                      <BrainCircuit className={`w-5 h-5 ${includeSolutions ? 'text-blue-600' : 'text-gray-400'}`} />
                      <div>
                        <h4 className="font-bold text-gray-900 text-sm">Giải toán chi tiết</h4>
                        <p className="text-[10px] text-gray-500">Lời giải từng bước bằng AI.</p>
                      </div>
                    </div>
                    <div className={`h-5 w-9 rounded-full relative transition-colors ${includeSolutions ? 'bg-blue-600' : 'bg-gray-200'}`}>
                      <span className={`absolute top-1 left-1 h-3 w-3 rounded-full bg-white transition-transform ${includeSolutions ? 'translate-x-4' : ''}`} />
                    </div>
                  </div>

                  <div className={`p-4 rounded-xl border-2 transition-all flex items-center justify-between cursor-pointer ${generateSimilar ? 'bg-indigo-50 border-indigo-200 shadow-sm' : 'bg-white border-gray-100 hover:border-gray-200'}`} onClick={() => setGenerateSimilar(!generateSimilar)}>
                    <div className="flex items-center gap-3">
                      <Layers className={`w-5 h-5 ${generateSimilar ? 'text-indigo-600' : 'text-gray-400'}`} />
                      <div>
                        <h4 className="font-bold text-gray-900 text-sm">Bài tập tương tự</h4>
                        <p className="text-[10px] text-gray-500">Mỗi câu gốc tạo N câu mới.</p>
                      </div>
                    </div>
                    <div className={`h-5 w-9 rounded-full relative transition-colors ${generateSimilar ? 'bg-indigo-600' : 'bg-gray-200'}`}>
                      <span className={`absolute top-1 left-1 h-3 w-3 rounded-full bg-white transition-transform ${generateSimilar ? 'translate-x-4' : ''}`} />
                    </div>
                  </div>
                </div>

              {/* 2. Tùy chọn định dạng */}
              <div>
                <label className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 block">Định dạng Công thức</label>
                <div className="grid grid-cols-2 gap-2 bg-gray-50 p-1.5 rounded-lg border border-gray-100">
                  <button 
                    onClick={() => setMathFormat('latex')}
                    className={`flex items-center justify-center gap-2 py-2.5 rounded-md text-xs font-bold transition-all ${mathFormat === 'latex' ? 'bg-white text-blue-600 shadow-sm border border-blue-100' : 'text-gray-400 hover:text-gray-600'}`}
                  >
                    <Binary className="w-4 h-4" />
                    LaTeX ($...$)
                  </button>
                  <button 
                    onClick={() => setMathFormat('equation')}
                    className={`flex items-center justify-center gap-2 py-2.5 rounded-md text-xs font-bold transition-all ${mathFormat === 'equation' ? 'bg-white text-blue-600 shadow-sm border border-blue-100' : 'text-gray-400 hover:text-gray-600'}`}
                  >
                    <FunctionSquare className="w-4 h-4" />
                    Word Equation
                  </button>
                </div>
              </div>

              {generateSimilar && (
                <div className="pt-4 border-t border-gray-100 animate-fade-in space-y-4">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-gray-600">Số bài mới cho mỗi câu gốc: {similarCount}</label>
                      <input type="range" min="1" max="5" value={similarCount} onChange={(e) => setSimilarCount(parseInt(e.target.value))} className="w-full accent-indigo-600" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-gray-600">Mức độ tương đồng:</label>
                      <div className="flex bg-gray-100 p-1 rounded-md text-[10px]">
                        <button onClick={() => setSimilarityLevel('numbers')} className={`flex-1 py-1 rounded ${similarityLevel === 'numbers' ? 'bg-white shadow-sm text-indigo-600 font-bold' : 'text-gray-400'}`}>Chỉ đổi số</button>
                        <button onClick={() => setSimilarityLevel('type')} className={`flex-1 py-1 rounded ${similarityLevel === 'type' ? 'bg-white shadow-sm text-indigo-600 font-bold' : 'text-gray-400'}`}>Dạng bài</button>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* Trạng thái IDLE: Hiển thị Upload */}
            {status === AppStatus.IDLE && (
                <FileUpload onFileSelect={handleFileSelect} disabled={false} />
            )}

            {/* Trạng thái READY: Hiển thị danh sách file và nút Start */}
            {status === AppStatus.READY && (
                <div className="animate-fade-in space-y-4">
                    <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                        <div className="p-4 bg-gray-50 border-b border-gray-200 flex items-center justify-between">
                            <div className="flex items-center gap-2">
                                <FileStack className="w-5 h-5 text-blue-600" />
                                <span className="font-bold text-gray-700 text-sm">Tệp đã chọn ({currentFiles.length})</span>
                            </div>
                        </div>
                        <div className="max-h-60 overflow-y-auto p-2 space-y-2 custom-scrollbar">
                            {currentFiles.map((file, idx) => (
                                <div key={idx} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg border border-gray-100 group">
                                    <div className="flex items-center gap-3 overflow-hidden">
                                        <div className="w-8 h-8 rounded bg-white border border-gray-200 flex items-center justify-center flex-shrink-0">
                                            {file.type.startsWith('image/') ? (
                                                <img src={file.base64} className="w-full h-full object-cover rounded" />
                                            ) : (
                                                <span className="text-[10px] font-bold text-gray-500">{file.name.split('.').pop()?.toUpperCase()}</span>
                                            )}
                                        </div>
                                        <span className="text-sm text-gray-600 truncate">{file.name}</span>
                                    </div>
                                    <button 
                                        onClick={() => handleRemoveFile(idx)}
                                        className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-md transition-colors"
                                    >
                                        <X className="w-4 h-4" />
                                    </button>
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="flex items-center gap-3">
                        <button 
                            onClick={handleReset}
                            className="flex-1 py-3.5 bg-gray-100 hover:bg-gray-200 text-gray-600 rounded-xl font-bold text-sm flex items-center justify-center gap-2 transition-colors"
                        >
                            <Trash2 className="w-4 h-4" />
                            Hủy bỏ
                        </button>
                        <button 
                            onClick={handleStartProcessing}
                            className="flex-[2] py-3.5 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold text-sm flex items-center justify-center gap-2 shadow-lg shadow-blue-200 transition-all hover:scale-[1.01] active:scale-[0.99]"
                        >
                            <Play className="w-4 h-4 fill-current" />
                            Bắt đầu xử lý
                        </button>
                    </div>
                </div>
            )}
          </div>
        )}

        {status === AppStatus.CROP_SELECT && currentFiles.length > 0 && (
            <ImageCropper 
              files={currentFiles} 
              externalCrops={croppedImages}
              onComplete={handleCropComplete} 
              onCancel={handleCropCancel} 
            />
        )}

        {(status === AppStatus.PROCESSING) && (
          <ProcessingView files={fileProgress} isComplete={false} onCancel={handleCancelProcess} />
        )}

        {status === AppStatus.COMPLETE && results.length > 0 && (
          <ResultPreview results={results} onReset={handleReset} />
        )}

        {status === AppStatus.ERROR && (
          <div className="bg-white rounded-xl shadow-lg border border-red-100 p-8 text-center max-w-md mx-auto animate-fade-in">
             <AlertTriangle className="w-12 h-12 text-red-500 mx-auto mb-4" />
             <h3 className="text-lg font-bold text-gray-900">Lỗi xử lý</h3>
             <p className="text-gray-600 mt-2 mb-6">{errorMessage}</p>
             <button onClick={() => setStatus(AppStatus.READY)} className="px-8 py-2 bg-gray-900 text-white rounded-lg hover:bg-black transition-colors">Quay lại</button>
          </div>
        )}
      </main>

      <footer className="py-6 border-t border-gray-200 bg-white mt-auto text-center text-xs text-gray-400">
        © {new Date().getFullYear()} AI Document Hub. Multi-file Processing Enabled.
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { Loader2, CheckCircle2, FileText, XCircle, Clock, Ban } from 'lucide-react';

interface FileProgress {
  name: string;
  status: 'waiting' | 'processing' | 'complete' | 'error';
}

interface ProcessingViewProps {
  files: FileProgress[];
  isComplete: boolean;
  onCancel?: () => void;
}

export const ProcessingView: React.FC<ProcessingViewProps> = ({ files, isComplete, onCancel }) => {
  const completeCount = files.filter(f => f.status === 'complete').length;
  const totalCount = files.length;

  return (
    <div className="w-full max-w-2xl mx-auto bg-white rounded-2xl shadow-sm border border-gray-200 p-8 text-center animate-fade-in">
      <div className="flex flex-col items-center justify-center space-y-6">
        <div className="relative">
           {isComplete ? (
             <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center animate-scale-up">
               <CheckCircle2 className="w-10 h-10 text-green-600" />
             </div>
           ) : (
             <div className="w-20 h-20 bg-blue-50 rounded-full flex items-center justify-center">
               <Loader2 className="w-10 h-10 text-blue-600 animate-spin" />
             </div>
           )}
        </div>

        <div className="space-y-2">
          <h3 className="text-xl font-bold text-gray-800">
            {isComplete ? 'Chuyển đổi hoàn tất!' : `Đang xử lý ${totalCount} tài liệu...`}
          </h3>
          {!isComplete && (
            <div className="w-full bg-gray-100 h-2 rounded-full max-w-xs mx-auto overflow-hidden">
               <div 
                className="bg-blue-600 h-full transition-all duration-500" 
                style={{ width: `${(completeCount / totalCount) * 100}%` }}
               />
            </div>
          )}
          <p className="text-gray-500 max-w-md mx-auto text-sm">
            {isComplete 
              ? 'Tất cả tài liệu đã sẵn sàng.' 
              : `Hoàn thành: ${completeCount}/${totalCount}. AI đang phân tích song song các tệp.`}
          </p>
        </div>

        <div className="w-full max-w-md space-y-2 max-h-60 overflow-y-auto pr-2 custom-scrollbar">
          {files.map((file, idx) => (
            <div key={idx} className="flex items-center justify-between gap-3 px-4 py-3 bg-gray-50 rounded-xl border border-gray-100">
              <div className="flex items-center gap-3 overflow-hidden">
                <div className="bg-white p-2 rounded-lg border border-gray-200 shadow-sm flex-shrink-0">
                  <FileText className={`w-4 h-4 ${file.status === 'error' ? 'text-red-500' : 'text-blue-500'}`} />
                </div>
                <p className="text-xs font-medium text-gray-700 truncate text-left">{file.name}</p>
              </div>
              <div className="flex-shrink-0">
                {file.status === 'processing' && <Loader2 className="w-4 h-4 text-blue-600 animate-spin" />}
                {file.status === 'complete' && <CheckCircle2 className="w-4 h-4 text-green-500" />}
                {file.status === 'waiting' && <Clock className="w-4 h-4 text-gray-300" />}
                {file.status === 'error' && <XCircle className="w-4 h-4 text-red-500" />}
              </div>
            </div>
          ))}
        </div>

        {!isComplete && onCancel && (
          <button 
            onClick={onCancel}
            className="mt-4 px-6 py-2.5 bg-white border border-red-200 text-red-600 rounded-xl font-bold text-sm hover:bg-red-50 hover:border-red-300 hover:shadow-sm transition-all flex items-center gap-2 mx-auto group"
          >
            <Ban className="w-4 h-4 group-hover:scale-110 transition-transform" />
            DỪNG VÀ HỦY XỬ LÝ
          </button>
        )}
      </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Header } from './components/Header';
import { FileUpload } from './components/FileUpload';
import { ProcessingView } from './components/ProcessingView';
import { ResultPreview } from './components/ResultPreview';
import { ImageCropper } from './components/ImageCropper';
import { AppStatus, ConversionResult, FileData, CroppedImage, SimilarityLevel, MathFormat } from './types';
import { convertDocument } from './services/geminiService';
import { AlertTriangle, BrainCircuit, Layers, FunctionSquare, Binary, FileStack, X, Play, Trash2 } from 'lucide-react';

interface FileProcessingState {
  name: string;
  status: 'waiting' | 'processing' | 'complete' | 'error';
}

const App: React.FC = () => {
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [currentFiles, setCurrentFiles] = useState<FileData[]>([]);
  const [results, setResults] = useState<ConversionResult[]>([]);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [croppedImages, setCroppedImages] = useState<CroppedImage[]>([]);
  const [fileProgress, setFileProgress] = useState<FileProcessingState[]>([]);

  // Sử dụng runId để quản lý phiên xử lý, tránh xung đột khi hủy và chạy lại nhanh
  const activeRunId = useRef<number>(0);

  const [includeSolutions, setIncludeSolutions] = useState<boolean>(false);
  const [generateSimilar, setGenerateSimilar] = useState<boolean>(false);
  const [similarCount, setSimilarCount] = useState<number>(1);
  const [similarityLevel, setSimilarityLevel] = useState<SimilarityLevel>('numbers');
  const [mathFormat, setMathFormat] = useState<MathFormat>('latex');

  const processAllFiles = async (files: FileData[], images: CroppedImage[]) => {
    const runId = Date.now();
    activeRunId.current = runId;

    setResults([]);
    setFileProgress(files.map(f => ({ name: f.name, status: 'waiting' })));

    const conversionPromises = files.map(async (file, index) => {
      // Chỉ cập nhật trạng thái nếu phiên chạy này vẫn còn hiệu lực
      if (activeRunId.current !== runId) return null;

      setFileProgress(prev => {
        const next = [...prev];
        if (next[index]) next[index].status = 'processing';
        return next;
      });

      try {
        const htmlContent = await convertDocument(
          file, 
          // Gửi toàn bộ ảnh đã cắt cho từng file, AI sẽ tự tìm ảnh phù hợp với nội dung
          images, 
          includeSolutions, 
          generateSimilar, 
          similarCount, 
          similarityLevel,
          mathFormat
        );

        if (activeRunId.current !== runId) return null;

        setFileProgress(prev => {
          const next = [...prev];
          if (next[index]) next[index].status = 'complete';
          return next;
        });

        return { content: htmlContent, fileName: file.name };
      } catch (error) {
        if (activeRunId.current !== runId) return null;

        console.error(`Error processing ${file.name}:`, error);
        setFileProgress(prev => {
          const next = [...prev];
          if (next[index]) next[index].status = 'error';
          return next;
        });
        return null;
      }
    });

    const finalResults = await Promise.all(conversionPromises);

    if (activeRunId.current !== runId) return;

    const successfulResults = finalResults.filter((r): r is ConversionResult => r !== null);

    if (successfulResults.length === 0) {
      setStatus(AppStatus.ERROR);
      setErrorMessage("Không thể chuyển đổi bất kỳ tệp nào. Vui lòng kiểm tra lại tệp đầu vào.");
    } else {
      setResults(successfulResults);
      setStatus(AppStatus.COMPLETE);
    }
  };

  const handleFileSelect = useCallback((files: FileList) => {
    setErrorMessage(null);
    setCroppedImages([]);
    const fileArray = Array.from(files);

    const loadFiles = async () => {
      const fileDataPromises = fileArray.map(file => {
        return new Promise<FileData>((resolve) => {
          const reader = new FileReader();
          reader.onload = (e) => {
            resolve({
              name: file.name,
              size: file.size,
              type: file.type,
              base64: e.target?.result as string
            });
          };
          reader.readAsDataURL(file);
        });
      });

      const loadedFiles = await Promise.all(fileDataPromises);
      setCurrentFiles(loadedFiles);
      setStatus(AppStatus.READY); // Chuyển sang trạng thái READY
    };

    loadFiles();
  }, []);

  useEffect(() => {
    const handlePaste = async (event: ClipboardEvent) => {
      const items = event.clipboardData?.items;
      if (!items) return;

      const imageBlobs: File[] = [];
      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const blob = items[i].getAsFile();
          if (blob) imageBlobs.push(blob);
        }
      }

      if (imageBlobs.length === 0) return;

      const blobToCrop = (blob: File, index: number): Promise<CroppedImage> => {
        return new Promise((resolve) => {
          const reader = new FileReader();
          reader.onload = (e) => {
            resolve({
              id: `pasted-${Date.now()}-${index}`,
              base64: e.target?.result as string,
              page: 0
            });
          };
          reader.readAsDataURL(blob);
        });
      };

      if (status === AppStatus.IDLE) {
        const firstBlob = imageBlobs[0];
        const reader = new FileReader();
        reader.onload = async (e) => {
          const base64 = e.target?.result as string;
          const fileData: FileData = {
            name: `pasted-images-${Date.now()}.png`,
            size: firstBlob.size,
            type: firstBlob.type,
            base64: base64
          };
          setCurrentFiles([fileData]);

          const newCrops = await Promise.all(imageBlobs.map((blob, idx) => blobToCrop(blob, idx)));
          setCroppedImages(newCrops);
          setStatus(AppStatus.CROP_SELECT);
        };
        reader.readAsDataURL(firstBlob);
      } else if (status === AppStatus.CROP_SELECT) {
        const newCrops = await Promise.all(imageBlobs.map((blob, idx) => blobToCrop(blob, idx)));
        setCroppedImages(prev => [...prev, ...newCrops]);
      } else if (status === AppStatus.READY) {
          const newFilesPromises = imageBlobs.map(blob => new Promise<FileData>((resolve) => {
             const reader = new FileReader();
             reader.onload = (e) => resolve({
                 name: `pasted-${Date.now()}.png`,
                 size: blob.size,
                 type: blob.type,
                 base64: e.target?.result as string
             });
             reader.readAsDataURL(blob);
          }));
          const newFiles = await Promise.all(newFilesPromises);
          setCurrentFiles(prev => [...prev, ...newFiles]);
      }
    };

    window.addEventListener('paste', handlePaste);
    return () => window.removeEventListener('paste', handlePaste);
  }, [status]);

  const handleStartProcessing = () => {
      const hasCroppable = currentFiles.some(f => f.type === 'application/pdf' || f.type.startsWith('image/'));

      if (hasCroppable) {
        setStatus(AppStatus.CROP_SELECT);
      } else {
        setStatus(AppStatus.PROCESSING);
        processAllFiles(currentFiles, []);
      }
  };

  const handleReset = () => {
      setStatus(AppStatus.IDLE);
      setCurrentFiles([]);
      setCroppedImages([]);
      setFileProgress([]);
  };

  const handleRemoveFile = (index: number) => {
      const newFiles = [...currentFiles];
      newFiles.splice(index, 1);
      if (newFiles.length === 0) {
          handleReset();
      } else {
          setCurrentFiles(newFiles);
      }
  };

  const handleCropComplete = (images: CroppedImage[]) => {
    setCroppedImages(images);
    if (currentFiles.length > 0) {
        setStatus(AppStatus.PROCESSING);
        processAllFiles(currentFiles, images);
    }
  };

  const handleCropCancel = () => {
      if (currentFiles.length > 0) {
          setStatus(AppStatus.PROCESSING);
          processAllFiles(currentFiles, []);
      }
  };

  const handleCancelProcess = () => {
    activeRunId.current = 0; // Vô hiệu hóa runId hiện tại
    setStatus(AppStatus.READY);
    setFileProgress([]);
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8FAFC]">
      <Header />

      <main className="flex-grow container mx-auto px-4 py-8 flex flex-col items-center justify-start gap-6 relative">

        {(status === AppStatus.IDLE || status === AppStatus.READY) && (
          <div className="text-center max-w-2xl mx-auto mb-2">
            <h2 className="text-4xl font-extrabold text-gray-900 tracking-tight mb-2">
              Chuyển đổi <span className="text-blue-600">Đa tệp</span>
            </h2>
            <p className="text-gray-600">Trích xuất văn bản & hỗ trợ Equation/LaTeX cho Microsoft Word.</p>
          </div>
        )}

        {(status === AppStatus.IDLE || status === AppStatus.READY) && (
          <div className="w-full max-w-2xl mx-auto space-y-4">

            {/* Options Panel */}
            <div className="bg-white p-5 rounded-xl border border-gray-200 shadow-sm space-y-5 animate-fade-in-up">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  <div className={`p-4 rounded-xl border-2 transition-all flex items-center justify-between cursor-pointer ${includeSolutions ? 'bg-blue-50 border-blue-200 shadow-sm' : 'bg-white border-gray-100 hover:border-gray-200'}`} onClick={() => setIncludeSolutions(!includeSolutions)}>
                    <div className="flex items-center gap-3">
                      <BrainCircuit className={`w-5 h-5 ${includeSolutions ? 'text-blue-600' : 'text-gray-400'}`} />
                      <div>
                        <h4 className="font-bold text-gray-900 text-sm">Giải toán chi tiết</h4>
                        <p className="text-[10px] text-gray-500">Lời giải từng bước bằng AI.</p>
                      </div>
                    </div>
                    <div className={`h-5 w-9 rounded-full relative transition-colors ${includeSolutions ? 'bg-blue-600' : 'bg-gray-200'}`}>
                      <span className={`absolute top-1 left-1 h-3 w-3 rounded-full bg-white transition-transform ${includeSolutions ? 'translate-x-4' : ''}`} />
                    </div>
                  </div>

                  <div className={`p-4 rounded-xl border-2 transition-all flex items-center justify-between cursor-pointer ${generateSimilar ? 'bg-indigo-50 border-indigo-200 shadow-sm' : 'bg-white border-gray-100 hover:border-gray-200'}`} onClick={() => setGenerateSimilar(!generateSimilar)}>
                    <div className="flex items-center gap-3">
                      <Layers className={`w-5 h-5 ${generateSimilar ? 'text-indigo-600' : 'text-gray-400'}`} />
                      <div>
                        <h4 className="font-bold text-gray-900 text-sm">Bài tập tương tự</h4>
                        <p className="text-[10px] text-gray-500">Mỗi câu gốc tạo N câu mới.</p>
                      </div>
                    </div>
                    <div className={`h-5 w-9 rounded-full relative transition-colors ${generateSimilar ? 'bg-indigo-600' : 'bg-gray-200'}`}>
                      <span className={`absolute top-1 left-1 h-3 w-3 rounded-full bg-white transition-transform ${generateSimilar ? 'translate-x-4' : ''}`} />
                    </div>
                  </div>
                </div>

              <div>
                <label className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2 block">Định dạng Công thức</label>
                <div className="grid grid-cols-2 gap-2 bg-gray-50 p-1.5 rounded-lg border border-gray-100">
                  <button 
                    onClick={() => setMathFormat('latex')}
                    className={`flex items-center justify-center gap-2 py-2.5 rounded-md text-xs font-bold transition-all ${mathFormat === 'latex' ? 'bg-white text-blue-600 shadow-sm border border-blue-100' : 'text-gray-400 hover:text-gray-600'}`}
                  >
                    <Binary className="w-4 h-4" />
                    LaTeX ($...$)
                  </button>
                  <button 
                    onClick={() => setMathFormat('equation')}
                    className={`flex items-center justify-center gap-2 py-2.5 rounded-md text-xs font-bold transition-all ${mathFormat === 'equation' ? 'bg-white text-blue-600 shadow-sm border border-blue-100' : 'text-gray-400 hover:text-gray-600'}`}
                  >
                    <FunctionSquare className="w-4 h-4" />
                    Word Equation
                  </button>
                </div>
              </div>

              {generateSimilar && (
                <div className="pt-4 border-t border-gray-100 animate-fade-in space-y-4">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-gray-600">Số bài mới cho mỗi câu gốc: {similarCount}</label>
                      <input type="range" min="1" max="5" value={similarCount} onChange={(e) => setSimilarCount(parseInt(e.target.value))} className="w-full accent-indigo-600" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-gray-600">Mức độ tương đồng:</label>
                      <div className="flex bg-gray-100 p-1 rounded-md text-[10px]">
                        <button onClick={() => setSimilarityLevel('numbers')} className={`flex-1 py-1 rounded ${similarityLevel === 'numbers' ? 'bg-white shadow-sm text-indigo-600 font-bold' : 'text-gray-400'}`}>Chỉ đổi số</button>
                        <button onClick={() => setSimilarityLevel('type')} className={`flex-1 py-1 rounded ${similarityLevel === 'type' ? 'bg-white shadow-sm text-indigo-600 font-bold' : 'text-gray-400'}`}>Dạng bài</button>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>

            {status === AppStatus.IDLE && (
                <FileUpload onFileSelect={handleFileSelect} disabled={false} />
            )}

            {status === AppStatus.READY && (
                <div className="animate-fade-in space-y-4">
                    <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                        <div className="p-4 bg-gray-50 border-b border-gray-200 flex items-center justify-between">
                            <div className="flex items-center gap-2">
                                <FileStack className="w-5 h-5 text-blue-600" />
                                <span className="font-bold text-gray-700 text-sm">Tệp đã chọn ({currentFiles.length})</span>
                            </div>
                        </div>
                        <div className="max-h-60 overflow-y-auto p-2 space-y-2 custom-scrollbar">
                            {currentFiles.map((file, idx) => (
                                <div key={idx} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg border border-gray-100 group">
                                    <div className="flex items-center gap-3 overflow-hidden">
                                        <div className="w-8 h-8 rounded bg-white border border-gray-200 flex items-center justify-center flex-shrink-0">
                                            {file.type.startsWith('image/') ? (
                                                <img src={file.base64} className="w-full h-full object-cover rounded" />
                                            ) : (
                                                <span className="text-[10px] font-bold text-gray-500">{file.name.split('.').pop()?.toUpperCase()}</span>
                                            )}
                                        </div>
                                        <span className="text-sm text-gray-600 truncate">{file.name}</span>
                                    </div>
                                    <button 
                                        onClick={() => handleRemoveFile(idx)}
                                        className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-md transition-colors"
                                    >
                                        <X className="w-4 h-4" />
                                    </button>
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="flex items-center gap-3">
                        <button 
                            onClick={handleReset}
                            className="flex-1 py-3.5 bg-gray-100 hover:bg-gray-200 text-gray-600 rounded-xl font-bold text-sm flex items-center justify-center gap-2 transition-colors"
                        >
                            <Trash2 className="w-4 h-4" />
                            Hủy bỏ
                        </button>
                        <button 
                            onClick={handleStartProcessing}
                            className="flex-[2] py-3.5 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold text-sm flex items-center justify-center gap-2 shadow-lg shadow-blue-200 transition-all hover:scale-[1.01] active:scale-[0.99]"
                        >
                            <Play className="w-4 h-4 fill-current" />
                            Bắt đầu xử lý
                        </button>
                    </div>
                </div>
            )}
          </div>
        )}

        {status === AppStatus.CROP_SELECT && currentFiles.length > 0 && (
            <ImageCropper 
              files={currentFiles} 
              externalCrops={croppedImages}
              onComplete={handleCropComplete} 
              onCancel={handleCropCancel} 
            />
        )}

        {(status === AppStatus.PROCESSING) && (
          <ProcessingView files={fileProgress} isComplete={false} onCancel={handleCancelProcess} />
        )}

        {status === AppStatus.COMPLETE && results.length > 0 && (
          <ResultPreview results={results} onReset={handleReset} />
        )}

        {status === AppStatus.ERROR && (
          <div className="bg-white rounded-xl shadow-lg border border-red-100 p-8 text-center max-w-md mx-auto animate-fade-in">
             <AlertTriangle className="w-12 h-12 text-red-500 mx-auto mb-4" />
             <h3 className="text-lg font-bold text-gray-900">Lỗi xử lý</h3>
             <p className="text-gray-600 mt-2 mb-6">{errorMessage}</p>
             <button onClick={() => setStatus(AppStatus.READY)} className="px-8 py-2 bg-gray-900 text-white rounded-lg hover:bg-black transition-colors">Quay lại</button>
          </div>
        )}
      </main>

      <footer className="py-6 border-t border-gray-200 bg-white mt-auto text-center text-xs text-gray-400">
        © {new Date().getFullYear()} AI Document Hub. Multi-file Processing Enabled.
      </footer>
    </div>
  );
};

export default App;
